@Slf4j
@RequiredArgsConstructor
class MicrobotWorldSupplier implements Supplier<World>
{
    private final OkHttpClient okHttpClient;
    private final Random random = new Random(System.nanoTime());
    private final Queue<World> worlds = new ArrayDeque<>();

    @Override
    public World get()
    {
        if (!worlds.isEmpty())
        {
            return worlds.poll();
        }

        try
        {
            List<World> newWorlds = new WorldClient(okHttpClient, HttpUrl.get(RuneLiteProperties.getApiBase()))
                .lookupWorlds()
                .getWorlds()
                .stream()
                .filter(w -> w.getTypes().isEmpty() || EnumSet.of(WorldType.MEMBERS).equals(w.getTypes()))
                .collect(Collectors.toList());

            Collections.shuffle(newWorlds, random);

            worlds.addAll(newWorlds.subList(0, 16));
        }
        catch (IOException e)
        {
            log.warn("Unable to retrieve world list", e);
        }

        while (worlds.size() < 2)
        {
            int id = random.nextInt(50) + 1;
            World world = World.builder()
                .id(300 + id) // worlds start at 300
                .address("oldschool" + id + ".runescape.COM")
                .build();
            worlds.add(world);
        }

        return worlds.poll();
    }
}

// ----- RandomFactClient (net.runelite.client.plugins.microbot) -----
/**
 * Client to fetch random facts from the microbot API.
 */
@Slf4j
public class RandomFactClient {
    private static final String MICROBOT_API_URL = "https://microbot.cloud/api";
    private static final OkHttpClient client = new OkHttpClient.Builder()
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(10, TimeUnit.SECONDS)
            .build();

    /**
     * Fetches a random fact from the microbot API.
     * @return random fact string or error message
     */
    public static String getRandomFact() {
        try {
            Request request = new Request.Builder()
                .url(MICROBOT_API_URL + "/fact/random")
                .build();

            try (Response response = client.newCall(request).execute()) {
                if (!response.isSuccessful() || response.body() == null) {
                return "Failed to fetch random fact";
                }
                return response.body().string();
            }
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Fetches a random fact asynchronously and invokes the callback on the Swing EDT.
     * @param callback
     */
    public static void getRandomFactAsync(Consumer<String> callback) {
        CompletableFuture.supplyAsync(() -> {
            try {
                return getRandomFact();
            } catch (Exception e) {
                log.error("Error in async fact fetching", e);
            }
            return null;
        }).thenAccept(fact -> {
            // Ensure UI update happens on EDT
            SwingUtilities.invokeLater(() -> callback.accept(fact));
        }).exceptionally(throwable -> {
            log.error("Async fact fetching failed", throwable);
            return null;
        });
    }
}

// ----- Script (net.runelite.client.plugins.microbot) -----
@Slf4j
public abstract class Script extends Global implements IScript {
    protected ScheduledExecutorService scheduledExecutorService = Executors.newScheduledThreadPool(10,
        new ThreadFactory() {
            private final AtomicInteger threadNumber = new AtomicInteger(1);
            @Override
            public Thread newThread(@NotNull Runnable r) {
                Thread t = new Thread(r);
                t.setName(Script.this.getClass().getSimpleName() + "-" + threadNumber.getAndIncrement());
                return t;
            }
        });
    protected ScheduledFuture<?> scheduledFuture;
    protected ScheduledFuture<?> mainScheduledFuture;

    public boolean isRunning() {
        return mainScheduledFuture != null && !mainScheduledFuture.isDone();
    }

    @Getter
    protected static WorldPoint initialPlayerLocation;

    public void shutdown() {
        if (mainScheduledFuture != null && !mainScheduledFuture.isDone()) {
            mainScheduledFuture.cancel(true);
            ShortestPathPlugin.exit();
            if (Microbot.getClientThread().scheduledFuture != null)
                Microbot.getClientThread().scheduledFuture.cancel(true);
            initialPlayerLocation = null;
            Microbot.pauseAllScripts.set(false);
            Rs2Walker.disableTeleports = false;
            Microbot.getSpecialAttackConfigs().reset();
            Rs2Walker.setTarget(null);
        }
        if (scheduledFuture != null && !scheduledFuture.isDone()) {
            scheduledFuture.cancel(true);
        }
    }

    public boolean run() {
        //Avoid executing any blocking events if the player hasn't finished Tutorial Island
        if (Microbot.isLoggedIn() && !Rs2Player.hasCompletedTutorialIsland())
            return true;

        if (Rs2Player.hasCompletedTutorialIsland() && Microbot.getBlockingEventManager().shouldBlockAndProcess()) {
            // A blocking event was found & is executing
            return false;
        }
        if (Microbot.pauseAllScripts.get())
            return false;
        if (Thread.currentThread().isInterrupted())
            return false;

        if (Microbot.isLoggedIn()) {
            boolean hasRunEnergy = Microbot.getClient().getEnergy() > Microbot.runEnergyThreshold;
            if (Microbot.enableAutoRunOn && hasRunEnergy)
                Rs2Player.toggleRunEnergy(true);
            if (!hasRunEnergy && Microbot.useStaminaPotsIfNeeded && Rs2Player.isMoving()) {
                Rs2Inventory.useRestoreEnergyItem();
            }
        }
        return true;
    }
}


