    {
        for (LedgerID ledger : values())
        {
            if (ledger.name.equalsIgnoreCase(name))
            {
                return ledger.objectId;
            }
        }
        return null;
    }

    public static boolean containsName(String name)
    {
        for (LedgerID ledger : values())
        {
            if (ledger.name.equalsIgnoreCase(name))
            {
                return true;
            }
        }
        return false;
    }
