// ----- CooksAssistantOverlay (net.runelite.client.plugins.microbot.cooksassistant) -----
@Slf4j
public class CooksAssistantOverlay extends OverlayPanel {

    private final CooksAssistantPlugin plugin;

    private static final String EGG = "Egg";
    private static final String BUCKET_OF_MILK = "Bucket of milk";
    private static final String POT_OF_FLOUR = "Pot of flour";

    @Inject
    CooksAssistantOverlay(CooksAssistantPlugin plugin) {
        super(plugin);
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        setNaughty();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        try {
            CooksAssistantScript script = plugin.getScript();

            panelComponent.getChildren().add(TitleComponent.builder()
                .text("Cook's Assistant")
                .color(Color.CYAN)
                .build());

            if (script == null) {
                panelComponent.getChildren().add(LineComponent.builder()
                .left("Status:")
                .right("Not initialized")
                .build());
                return super.render(graphics);
            }

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Status:")
                .right(script.getStatus())
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("State:")
                .right(script.getState().toString())
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Quest Progress:")
                .right(String.valueOf(script.getQuestProgress()))
                .build());

            // Item checklist
            panelComponent.getChildren().add(LineComponent.builder()
                .left("─────────────")
                .right("─────────────")
                .build());

            boolean hasEgg = Rs2Inventory.contains(EGG);
            boolean hasMilk = Rs2Inventory.contains(BUCKET_OF_MILK);
            boolean hasFlour = Rs2Inventory.contains(POT_OF_FLOUR);

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Egg:")
                .leftColor(Color.WHITE)
                .right(hasEgg ? "✓" : "✗")
                .rightColor(hasEgg ? Color.GREEN : Color.RED)
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Bucket of Milk:")
                .leftColor(Color.WHITE)
                .right(hasMilk ? "✓" : "✗")
                .rightColor(hasMilk ? Color.GREEN : Color.RED)
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Pot of Flour:")
                .leftColor(Color.WHITE)
                .right(hasFlour ? "✓" : "✗")
                .rightColor(hasFlour ? Color.GREEN : Color.RED)
                .build());

        } catch (Exception e) {
            log.error("Error in overlay: {}", e.getMessage());
        }

        return super.render(graphics);
    }
}

// ----- CooksAssistantPlugin (net.runelite.client.plugins.microbot.cooksassistant) -----
@PluginDescriptor(
        name = PluginDescriptor.Microbot + "Cook's Assistant",
        description = "Completes the Cook's Assistant quest automatically",
        tags = {"quest", "cooks", "assistant", "microbot"},
        enabledByDefault = false
)
@Slf4j
public class CooksAssistantPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private CooksAssistantConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private CooksAssistantOverlay overlay;

    private CooksAssistantScript script;

    @Provides
    CooksAssistantConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(CooksAssistantConfig.class);
    }

    @Override
    protected void startUp() throws Exception {
        script = new CooksAssistantScript(client);
        overlayManager.add(overlay);
        log.info("Cook's Assistant plugin started");
    }

    @Override
    protected void shutDown() throws Exception {
        if (script != null) {
            script.shutdown();
        }
        overlayManager.remove(overlay);
        log.info("Cook's Assistant plugin stopped");
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (config.startPlugin()) {
            if (!script.isRunning()) {
                script.run(config);
            }
        } else {
            if (script.isRunning()) {
                script.shutdown();
            }
        }
    }

    public CooksAssistantScript getScript() {
        return script;
    }

    public Client getClient() {
        return client;
    }
}

// ----- CooksAssistantScript (net.runelite.client.plugins.microbot.cooksassistant) -----
@Slf4j
public class CooksAssistantScript extends Script {

    @Getter
    private CooksAssistantState state = CooksAssistantState.STARTING;

    @Getter
    private String status = "Starting...";

    private final Client client;

    // Item names
    private static final String EGG = "Egg";
    private static final String BUCKET = "Bucket";
    private static final String BUCKET_OF_MILK = "Bucket of milk";
    private static final String POT = "Pot";
    private static final String POT_OF_FLOUR = "Pot of flour";
    private static final String GRAIN = "Grain";

    // Object names
    private static final String WHEAT = "Wheat";
    private static final String HOPPER = "Hopper";
    private static final String HOPPER_CONTROLS = "Hopper controls";
    private static final String FLOUR_BIN = "Flour bin";
    private static final String DAIRY_COW = "Dairy cow";
    private static final String LADDER = "Ladder";

    // NPC names
    private static final String COOK = "Cook";

    // Key Locations
    private static final WorldPoint COOK_LOCATION = new WorldPoint(3208, 3214, 0);
    private static final WorldPoint CHICKEN_COOP = new WorldPoint(3230, 3298, 0);
    private static final WorldPoint DAIRY_COW_LOCATION = new WorldPoint(3253, 3270, 0);
    private static final WorldPoint WHEAT_FIELD = new WorldPoint(3161, 3293, 0);
    private static final WorldPoint MILL_ENTRANCE = new WorldPoint(3166, 3306, 0);
    private static final WorldPoint LUMBRIDGE_BANK = new WorldPoint(3208, 3220, 2);

    // Quest varbit
    private static final int COOKS_ASSISTANT_VARBIT = 29;

    private CooksAssistantConfig config;

    public CooksAssistantScript(Client client) {
        this.client = client;
    }

    public boolean run(CooksAssistantConfig config) {
        this.config = config;
        mainScheduledFuture = scheduledExecutorService.scheduleWithFixedDelay(() -> {
            try {
                if (!isLoggedIn() || !super.run()) {
                return;
                }

                if (isQuestComplete()) {
                state = CooksAssistantState.QUEST_COMPLETE;
                status = "Quest already completed!";
                shutdown();
                return;
                }

                if (Rs2Dialogue.isInDialogue()) {
                handleDialogue();
                return;
                }

                executeState();

            } catch (Exception e) {
                log.error("Error in Cook's Assistant script", e);
            }
        }, 0, 600, TimeUnit.MILLISECONDS);

        return true;
    }

    private boolean isLoggedIn() {
        return client != null && client.getGameState() == GameState.LOGGED_IN;
    }

    private void executeState() {
        switch (state) {
            case STARTING:
                handleStarting();
                break;

            case CHECKING_BANK:
                handleCheckingBank();
                break;

            case BANKING:
                handleBanking();
                break;

            case WALKING_TO_CHICKEN_COOP:
                handleWalkingToChickenCoop();
                break;

            case COLLECTING_EGG:
                handleCollectingEgg();
                break;

            case WALKING_TO_COW:
                handleWalkingToCow();
                break;

            case MILKING_COW:
                handleMilkingCow();
                break;

            case WALKING_TO_WHEAT_FIELD:
                handleWalkingToWheatField();
                break;

            case PICKING_WHEAT:
                handlePickingWheat();
                break;

            case WALKING_TO_MILL_TOP:
                handleWalkingToMillTop();
                break;

            case USING_HOPPER:
                handleUsingHopper();
                break;

            case OPERATING_HOPPER:
                handleOperatingHopper();
                break;

            case WALKING_TO_MILL_BOTTOM:
                handleWalkingToMillBottom();
                break;

            case COLLECTING_FLOUR:
                handleCollectingFlour();
                break;

            case WALKING_TO_COOK:
                handleWalkingToCook();
                break;

            case TALKING_TO_COOK:
                handleTalkingToCook();
                break;

            case QUEST_COMPLETE:
                status = "Quest Complete!";
                shutdown();
                break;

            default:
                state = CooksAssistantState.STARTING;
                break;
        }
    }

    private void handleStarting() {
        status = "Checking inventory...";

        boolean hasEgg = Rs2Inventory.contains(EGG);
        boolean hasMilk = Rs2Inventory.contains(BUCKET_OF_MILK);
        boolean hasFlour = Rs2Inventory.contains(POT_OF_FLOUR);

        if (hasEgg && hasMilk && hasFlour) {
            state = CooksAssistantState.WALKING_TO_COOK;
            return;
        }

        if (config.useBank()) {
            state = CooksAssistantState.CHECKING_BANK;
            return;
        }

        determineNextCollection();
    }

    private void handleCheckingBank() {
        status = "Walking to bank...";

        if (!Rs2Bank.isOpen()) {
            if (Rs2Bank.isNearBank(15)) {
                Rs2Bank.openBank();
                sleepUntil(Rs2Bank::isOpen, 5000);
            } else {
                Rs2Walker.walkTo(LUMBRIDGE_BANK);
            }
            return;
        }

        status = "Checking bank for items...";
        state = CooksAssistantState.BANKING;
    }

    private void handleBanking() {
        if (!Rs2Bank.isOpen()) {
            state = CooksAssistantState.CHECKING_BANK;
            return;
        }

        status = "Withdrawing items...";

        boolean hasEgg = Rs2Inventory.contains(EGG);
        boolean hasMilk = Rs2Inventory.contains(BUCKET_OF_MILK);
        boolean hasFlour = Rs2Inventory.contains(POT_OF_FLOUR);

        if (!hasEgg && Rs2Bank.hasItem(EGG)) {
            Rs2Bank.withdrawOne(EGG);
            sleep(300, 600);
        }

        if (!hasMilk && Rs2Bank.hasItem(BUCKET_OF_MILK)) {
            Rs2Bank.withdrawOne(BUCKET_OF_MILK);
            sleep(300, 600);
        }

        if (!hasFlour && Rs2Bank.hasItem(POT_OF_FLOUR)) {
            Rs2Bank.withdrawOne(POT_OF_FLOUR);
            sleep(300, 600);
        }

        if (!hasMilk && !Rs2Bank.hasItem(BUCKET_OF_MILK)) {
            if (!Rs2Inventory.contains(BUCKET) && Rs2Bank.hasItem(BUCKET)) {
                Rs2Bank.withdrawOne(BUCKET);
                sleep(300, 600);
            }
        }

        if (!hasFlour && !Rs2Bank.hasItem(POT_OF_FLOUR)) {
            if (!Rs2Inventory.contains(POT) && Rs2Bank.hasItem(POT)) {
                Rs2Bank.withdrawOne(POT);
                sleep(300, 600);
            }
        }

        Rs2Bank.closeBank();
        sleepUntil(() -> !Rs2Bank.isOpen(), 2000);

        determineNextCollection();
    }

    private void determineNextCollection() {
        boolean hasEgg = Rs2Inventory.contains(EGG);
        boolean hasMilk = Rs2Inventory.contains(BUCKET_OF_MILK);
        boolean hasFlour = Rs2Inventory.contains(POT_OF_FLOUR);

        if (hasEgg && hasMilk && hasFlour) {
            state = CooksAssistantState.WALKING_TO_COOK;
        } else if (!hasEgg) {
            state = CooksAssistantState.WALKING_TO_CHICKEN_COOP;
        } else if (!hasMilk) {
            if (!Rs2Inventory.contains(BUCKET)) {
                status = "Need bucket for milk!";
                state = CooksAssistantState.CHECKING_BANK;
            } else {
                state = CooksAssistantState.WALKING_TO_COW;
            }
        } else if (!hasFlour) {
            if (!Rs2Inventory.contains(POT)) {
                status = "Need pot for flour!";
                state = CooksAssistantState.CHECKING_BANK;
            } else if (Rs2Inventory.contains(GRAIN)) {
                state = CooksAssistantState.WALKING_TO_MILL_TOP;
            } else {
                state = CooksAssistantState.WALKING_TO_WHEAT_FIELD;
            }
        }
    }

    // ============ EGG COLLECTION ============

    private void handleWalkingToChickenCoop() {
        status = "Walking to chicken coop...";

        if (Rs2Inventory.contains(EGG)) {
            determineNextCollection();
            return;
        }

        if (Rs2Player.getWorldLocation().distanceTo(CHICKEN_COOP) > 10) {
            Rs2Walker.walkTo(CHICKEN_COOP);
        } else {
            state = CooksAssistantState.COLLECTING_EGG;
        }
    }

    private void handleCollectingEgg() {
        status = "Collecting egg...";

        if (Rs2Inventory.contains(EGG)) {
            log.info("Got egg!");
            determineNextCollection();
            return;
        }

        if (Rs2Player.isMoving() || Rs2Player.isAnimating()) {
            return;
        }

        // Use Rs2TileItemCache for ground items
        if (Rs2TileItemCache.interact(EGG, "Take")) {
            sleepUntil(() -> Rs2Inventory.contains(EGG), 5000);
            return;
        }

        // Wait for egg spawn
        sleep(1000, 2000);
    }

    // ============ MILK COLLECTION ============

    private void handleWalkingToCow() {
        status = "Walking to dairy cow...";

        if (Rs2Inventory.contains(BUCKET_OF_MILK)) {
            determineNextCollection();
            return;
        }

        if (Rs2Player.getWorldLocation().distanceTo(DAIRY_COW_LOCATION) > 10) {
            Rs2Walker.walkTo(DAIRY_COW_LOCATION);
        } else {
            state = CooksAssistantState.MILKING_COW;
        }
    }

    private void handleMilkingCow() {
        status = "Milking cow...";

        if (Rs2Inventory.contains(BUCKET_OF_MILK)) {
            log.info("Got bucket of milk!");
            determineNextCollection();
            return;
        }

        if (!Rs2Inventory.contains(BUCKET)) {
            status = "No bucket! Need to get one.";
            state = CooksAssistantState.CHECKING_BANK;
            return;
        }

        if (Rs2Player.isMoving() || Rs2Player.isAnimating()) {
            return;
        }

        // Use Rs2TileObjectCache for game objects
        if (Rs2TileObjectCache.interact(DAIRY_COW, "Milk")) {
            sleepUntil(() -> Rs2Inventory.contains(BUCKET_OF_MILK), 5000);
        }
    }

    // ============ FLOUR COLLECTION ============

    private void handleWalkingToWheatField() {
        status = "Walking to wheat field...";

        if (Rs2Inventory.contains(GRAIN)) {
            state = CooksAssistantState.WALKING_TO_MILL_TOP;
            return;
        }

        if (Rs2Player.getWorldLocation().distanceTo(WHEAT_FIELD) > 10) {
            Rs2Walker.walkTo(WHEAT_FIELD);
        } else {
            state = CooksAssistantState.PICKING_WHEAT;
        }
    }

    private void handlePickingWheat() {
        status = "Picking wheat...";

        if (Rs2Inventory.contains(GRAIN)) {
            log.info("Got grain!");
            state = CooksAssistantState.WALKING_TO_MILL_TOP;
            return;
        }

        if (Rs2Player.isMoving() || Rs2Player.isAnimating()) {
            return;
        }

        // Use Rs2TileObjectCache for game objects
        if (Rs2TileObjectCache.interact(WHEAT, "Pick")) {
            sleepUntil(() -> Rs2Inventory.contains(GRAIN), 5000);
        }
    }

    private void handleWalkingToMillTop() {
        status = "Walking to mill (top floor)...";

        if (Rs2Inventory.contains(POT_OF_FLOUR)) {
            determineNextCollection();
            return;
        }

        int currentPlane = Rs2Player.getWorldLocation().getPlane();

        if (currentPlane == 0) {
            if (Rs2Player.getWorldLocation().distanceTo(MILL_ENTRANCE) > 10) {
                Rs2Walker.walkTo(MILL_ENTRANCE);
            } else {
                if (Rs2TileObjectCache.interact(LADDER, "Climb-up")) {
                sleepUntil(() -> Rs2Player.getWorldLocation().getPlane() > 0, 5000);
                }
            }
            return;
        }

        if (currentPlane == 1) {
            if (Rs2TileObjectCache.interact(LADDER, "Climb-up")) {
                sleepUntil(() -> Rs2Player.getWorldLocation().getPlane() == 2, 5000);
            }
            return;
        }

        if (currentPlane == 2) {
            state = CooksAssistantState.USING_HOPPER;
        }
    }

    private void handleUsingHopper() {
        status = "Using hopper...";

        if (!Rs2Inventory.contains(GRAIN)) {
            state = CooksAssistantState.OPERATING_HOPPER;
            return;
        }

        if (Rs2Player.isMoving() || Rs2Player.isAnimating()) {
            return;
        }

        // Use grain on hopper
        if (Rs2Inventory.use(GRAIN)) {
            sleep(300, 600);
            if (Rs2TileObjectCache.interact(HOPPER, "Use")) {
                sleepUntil(() -> !Rs2Inventory.contains(GRAIN), 5000);
            }
        }
    }

    private void handleOperatingHopper() {
        status = "Operating hopper controls...";

        if (Rs2Player.isMoving() || Rs2Player.isAnimating()) {
            return;
        }

        if (Rs2TileObjectCache.interact(HOPPER_CONTROLS, "Operate")) {
            sleepUntil(Rs2Player::isAnimating, 3000);
            sleep(1000, 1500);
            state = CooksAssistantState.WALKING_TO_MILL_BOTTOM;
        }
    }

    private void handleWalkingToMillBottom() {
        status = "Walking to mill (ground floor)...";

        int currentPlane = Rs2Player.getWorldLocation().getPlane();

        if (currentPlane > 0) {
            if (Rs2TileObjectCache.interact(LADDER, "Climb-down")) {
                sleepUntil(() -> Rs2Player.getWorldLocation().getPlane() < currentPlane, 5000);
            }
            return;
        }

        state = CooksAssistantState.COLLECTING_FLOUR;
    }

    private void handleCollectingFlour() {
        status = "Collecting flour...";

        if (Rs2Inventory.contains(POT_OF_FLOUR)) {
            log.info("Got pot of flour!");
            determineNextCollection();
            return;
        }

        if (!Rs2Inventory.contains(POT)) {
            status = "No pot! Need to get one.";
            state = CooksAssistantState.CHECKING_BANK;
            return;
        }

        if (Rs2Player.isMoving() || Rs2Player.isAnimating()) {
            return;
        }

        if (Rs2TileObjectCache.interact(FLOUR_BIN, "Empty")) {
            sleepUntil(() -> Rs2Inventory.contains(POT_OF_FLOUR), 5000);
        }
    }

    // ============ QUEST COMPLETION ============

    private void handleWalkingToCook() {
        status = "Walking to cook...";

        if (Rs2Player.getWorldLocation().distanceTo(COOK_LOCATION) > 5) {
            Rs2Walker.walkTo(COOK_LOCATION);
        } else {
            state = CooksAssistantState.TALKING_TO_COOK;
        }
    }

    private void handleTalkingToCook() {
        status = "Talking to cook...";

        if (Rs2Dialogue.isInDialogue()) {
            return;
        }

        if (Rs2Player.isMoving()) {
            return;
        }

        // Use Rs2NpcQueryable for NPC interactions
        if (Rs2NpcQueryable.interact(COOK, "Talk-to")) {
            sleepUntil(Rs2Dialogue::isInDialogue, 5000);
        }
    }

    private void handleDialogue() {
        status = "Handling dialogue...";

        if (Rs2Dialogue.hasSelectAnOption()) {
            if (Rs2Widget.hasWidget("What's wrong?")) {
                Rs2Dialogue.clickOption("What's wrong?");
            } else if (Rs2Widget.hasWidget("I'm always happy to help a cook in distress")) {
                Rs2Dialogue.clickOption("I'm always happy to help a cook in distress");
            } else if (Rs2Widget.hasWidget("Actually, I know where to find this stuff")) {
                Rs2Dialogue.clickOption("Actually, I know where to find this stuff");
            } else if (Rs2Widget.hasWidget("Yes")) {
                Rs2Dialogue.clickOption("Yes");
            } else {
                Rs2Dialogue.clickContinue();
            }
            sleep(300, 600);
            return;
        }

        if (Rs2Dialogue.hasContinue()) {
            Rs2Dialogue.clickContinue();
            sleep(300, 600);
            return;
        }

        if (isQuestComplete()) {
            state = CooksAssistantState.QUEST_COMPLETE;
            status = "Quest Complete!";
        }
    }

    private boolean isQuestComplete() {
        if (client == null) return false;
        return client.getVarbitValue(COOKS_ASSISTANT_VARBIT) >= 2;
    }

    public int getQuestProgress() {
        if (client == null) return 0;
        return client.getVarbitValue(COOKS_ASSISTANT_VARBIT);
    }

    @Override
    public void shutdown() {
        super.shutdown();
        state = CooksAssistantState.IDLE;
        status = "Stopped";
    }
}

// ----- CooksAssistantState (net.runelite.client.plugins.microbot.cooksassistant) -----
public enum CooksAssistantState {
    STARTING,
    CHECKING_BANK,
    BANKING,

    // Egg collection
    WALKING_TO_CHICKEN_COOP,
    COLLECTING_EGG,

    // Milk collection
    WALKING_TO_COW,
    MILKING_COW,

    // Flour collection (making it)
    WALKING_TO_WHEAT_FIELD,
    PICKING_WHEAT,
    WALKING_TO_MILL_TOP,
    USING_HOPPER,
    OPERATING_HOPPER,
    WALKING_TO_MILL_BOTTOM,
    COLLECTING_FLOUR,

    // Quest completion
    WALKING_TO_COOK,
    TALKING_TO_COOK,
    HANDLING_DIALOGUE,

    QUEST_COMPLETE,
    IDLE
}


