// ----- Pouch (net.runelite.client.plugins.microbot.pouch) -----
public enum Pouch {
    SMALL(new int[]{ItemID.RCU_POUCH_SMALL}, new int[]{3}, new int[]{3}, 1),
    MEDIUM(new int[]{ItemID.RCU_POUCH_MEDIUM, ItemID.RCU_POUCH_MEDIUM_DEGRADE}, new int[]{6}, new int[]{3}, 25),
    LARGE(new int[]{ItemID.RCU_POUCH_LARGE, ItemID.RCU_POUCH_LARGE_DEGRADE}, new int[]{9}, new int[]{7}, 50),
    GIANT(new int[]{ItemID.RCU_POUCH_GIANT, ItemID.RCU_POUCH_GIANT_DEGRADE}, new int[]{12}, new int[]{9}, 75),
    // degradedBaseHoldAmount for colossal pouch is dynamic, it starts at 35 and lowers
    // each time you use the degraded pouch. We'll see it to 25 to be safe
    // holdAmount -1 for colossal pouch because it is calculated based on the rc level
    COLOSSAL(new int[]{ItemID.RCU_POUCH_COLOSSAL, ItemID.RCU_POUCH_COLOSSAL_DEGRADE}, new int[]{8, 16, 27, 40}, new int[]{6, 13, 23, 35}, 25);

    private final int[] baseHoldAmount;

    private int getBaseHoldAmount() {
        int index = (this == COLOSSAL) ? getColossalHoldAmountIndex() : 0;
        return degraded ? degradedBaseHoldAmount[index] : baseHoldAmount[index];
    }

    private final int[] degradedBaseHoldAmount;

    @Getter(AccessLevel.PUBLIC)
    @Setter(AccessLevel.PACKAGE)
    private int[] itemIds;
    @Getter(AccessLevel.PUBLIC)
    @Setter(AccessLevel.PACKAGE)
    private int holding;
    @Getter
    private boolean degraded;
    @Getter(AccessLevel.PUBLIC)
    @Setter(AccessLevel.PACKAGE)
    private boolean unknown = true;
    @Getter(AccessLevel.PACKAGE)
    @Setter(AccessLevel.PACKAGE)
    private int levelRequired;

    Pouch(int[] itemIds, int[] holdAmount, int[] degradedHoldAmount, int levelRequired) {
        this.itemIds = itemIds;
        this.baseHoldAmount = holdAmount;
        this.degradedBaseHoldAmount = degradedHoldAmount;
        this.levelRequired = levelRequired;
    }

    public int getHoldAmount() {
        return degraded ? getDegradedBaseHoldAmount() : getBaseHoldAmount();
    }

    public int getRemaining() {
        final int holdAmount = degraded ? getDegradedBaseHoldAmount() : getBaseHoldAmount();
        return holdAmount - holding;
    }

    private int getDegradedBaseHoldAmount() {
        int index = (this == COLOSSAL) ? getColossalHoldAmountIndex() : 0;
        return degradedBaseHoldAmount[index];
    }

    void addHolding(int delta) {
        holding += delta;

        final int holdAmount = degraded ? getDegradedBaseHoldAmount() : getBaseHoldAmount();
        if (holding < 0) {
            holding = 0;
        }
        System.out.println(delta + " " + holding + " " + holdAmount);
        if (holding > holdAmount) {
            holding = holdAmount;
        }
    }

    void degrade(boolean state) {
        if (state != degraded) {
            degraded = state;
            final int holdAmount = degraded ? getDegradedBaseHoldAmount() : getBaseHoldAmount();
            holding = Math.min(holding, holdAmount);
        }
    }

    static Pouch forItem(int itemId) {
        switch (itemId) {
            case ItemID.RCU_POUCH_SMALL:
                return SMALL;
            case ItemID.RCU_POUCH_MEDIUM:
            case ItemID.RCU_POUCH_MEDIUM_DEGRADE:
                return MEDIUM;
            case ItemID.RCU_POUCH_LARGE:
            case ItemID.RCU_POUCH_LARGE_DEGRADE:
                return LARGE;
            case ItemID.RCU_POUCH_GIANT:
            case ItemID.RCU_POUCH_GIANT_DEGRADE:
                return GIANT;
            case ItemID.RCU_POUCH_COLOSSAL:
            case ItemID.RCU_POUCH_COLOSSAL_DEGRADE:
            case ItemID.DEVIOUS_GLOWINGPOUCH_COLOSSAL:
                return COLOSSAL;
            default:
                return null;
        }
    }

    public boolean fill() {
        if (!hasRequiredRunecraftingLevel()) return false;
        if (!hasItemsToFillPouch()) return false;
        if (!hasPouchInInventory()) return false;

        if (getRemaining() > 0) {
            for (int i = 0; i < itemIds.length; i++) {
                if (Rs2Inventory.interact(itemIds[i], "fill"))
                return true;
            }
        }

        return false;
    }

    public boolean empty() {
        if (!hasRequiredRunecraftingLevel()) return false;
        if (!hasPouchInInventory()) return false;

        if (getHolding() > 0) {
            for (int i = 0; i < itemIds.length; i++) {
                if (Rs2Inventory.interact(itemIds[i], "empty"))
                return true;
            }
        }

        return false;
    }

    public boolean check() {
        if (!hasRequiredRunecraftingLevel()) return false;

        for (int i = 0; i < itemIds.length; i++) {
            if (Rs2Inventory.interact(itemIds[i], "check"))
                return true;
        }

        return false;
    }

    public boolean hasRequiredRunecraftingLevel() {
        return Rs2Player.getSkillRequirement(Skill.RUNECRAFT, getLevelRequired());
    }

    public boolean hasItemsToFillPouch() {
        return Rs2Inventory.hasItem(ItemID.BLANKRUNE_HIGH) || Rs2Inventory.hasItem(ItemID.BLANKRUNE_DAEYALT) || Rs2Inventory.hasItem(ItemID.GOTR_GUARDIAN_ESSENCE);
    }

    public boolean hasPouchInInventory() {
        return Rs2Inventory.hasItem(itemIds);
    }

    public int getColossalHoldAmountIndex() {
        int runecraftLevel = Rs2Player.getBoostedSkillLevel(Skill.RUNECRAFT);

        if (runecraftLevel >= 85) {
            return 3;
        } else if (runecraftLevel >= 75) {
            return 2;
        } else if (runecraftLevel >= 50) {
            return 1;
        } else {
            return 0;
        }
    }
}

// ----- PouchOverlay (net.runelite.client.plugins.microbot.pouch) -----
public class PouchOverlay extends WidgetItemOverlay
{
    @Inject
    PouchOverlay()
    {
        showOnInventory();
    }

    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
    {
        final Pouch pouch = Pouch.forItem(itemId);
        if (pouch == null)
        {
            return;
        }

        final Rectangle bounds = itemWidget.getCanvasBounds();
        final TextComponent textComponent = new TextComponent();
        textComponent.setPosition(new Point(bounds.x - 1, bounds.y + 8));
        textComponent.setColor(Color.CYAN);
        if (pouch.isUnknown())
        {
            textComponent.setText("?");
        }
        else
        {
            textComponent.setText(Integer.toString(pouch.getHolding()));
        }
        textComponent.render(graphics);
    }
}

// ----- PouchScript (net.runelite.client.plugins.microbot.pouch) -----
public class PouchScript extends Script {
    private final int INVENTORY_SIZE = 28;

    private final Pattern POUCH_CHECK_MESSAGE = Pattern.compile("^There (?:is|are) ([a-z-]+)(?: pure| daeyalt)? essences? in this pouch\\.$");
    private final ImmutableMap<String, Integer> TEXT_TO_NUMBER = ImmutableMap.<String, Integer>builder()
            .put("no", 0)
            .put("one", 1)
            .put("two", 2)
            .put("three", 3)
            .put("four", 4)
            .put("five", 5)
            .put("six", 6)
            .put("seven", 7)
            .put("eight", 8)
            .put("nine", 9)
            .put("ten", 10)
            .put("eleven", 11)
            .put("twelve", 12)
            .put("thirteen", 13)
            .put("fourteen", 14)
            .put("fifteen", 15)
            .put("sixteen", 16)
            .put("seventeen", 17)
            .put("eighteen", 18)
            .put("nineteen", 19)
            .put("twenty", 20)
            .put("twenty-one", 21)
            .put("twenty-two", 22)
            .put("twenty-three", 23)
            .put("twenty-four", 24)
            .put("twenty-five", 25)
            .put("twenty-six", 26)
            .put("twenty-seven", 27)
            .put("twenty-eight", 28)
            .put("twenty-nine", 29)
            .put("thirty", 30)
            .put("thirty-one", 31)
            .put("thirty-two", 32)
            .put("thirty-three", 33)
            .put("thirty-four", 34)
            .put("thirty-five", 35)
            .put("thirty-six", 36)
            .put("thirty-seven", 37)
            .put("thirty-eight", 38)
            .put("thirty-nine", 39)
            .put("forty", 40)
            .build();

    private final Deque<ClickOperation> clickedItems = new ArrayDeque<>();
    private final Deque<ClickOperation> checkedPouches = new ArrayDeque<>();
    private int lastEssence;
    private int lastSpace;
    private boolean isRunning = false;

    public void startUp() {
        // Reset pouch state
        for (Pouch pouch : Pouch.values()) {
            pouch.setHolding(0);
            pouch.setUnknown(true);
            pouch.degrade(false);
        }

        lastEssence = lastSpace = -1;
        isRunning = true;
    }

    @Override
    public void shutdown() {
        isRunning = false;
        super.shutdown();
    }

    public void onChatMessage(ChatMessage event) {
        if (!isRunning || event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        if (!checkedPouches.isEmpty()) {
            Matcher matcher = POUCH_CHECK_MESSAGE.matcher(event.getMessage());
            if (matcher.matches()) {
                final int num = TEXT_TO_NUMBER.get(matcher.group(1));
                // Keep getting operations until we get a valid one
                do {
                final ClickOperation op = checkedPouches.pop();
                if (op.tick >= Microbot.getClient().getTickCount()) {
                Pouch pouch = op.pouch;
                pouch.setHolding(num);
                pouch.setUnknown(false);
                break;
                }
                }
                while (!checkedPouches.isEmpty());
            }
        } else if (!clickedItems.isEmpty()) {
            if (event.getMessage().contains("You cannot add any more")) {
                do {
                final ClickOperation op = clickedItems.pop();
                if (op.tick >= Microbot.getClient().getTickCount()) {
                Pouch pouch = op.pouch;
                pouch.setHolding(pouch.getHoldAmount());
                System.out.println(pouch.getHolding());
                pouch.setUnknown(false);
                break;
                }
                }
                while (!clickedItems.isEmpty());
            } else if (event.getMessage().contains("There is no")) {
                do {
                final ClickOperation op = clickedItems.pop();
                if (op.tick >= Microbot.getClient().getTickCount()) {
                Pouch pouch = op.pouch;
                pouch.setHolding(0);
                pouch.setUnknown(false);
                break;
                }
                }
                while (!clickedItems.isEmpty());
            }
        }
    }

    public void onItemContainerChanged(ItemContainerChanged event) {
        if (!isRunning)
            return;

        if (InventoryID.INV != event.getContainerId()) {
            return;
        }

        final Item[] items = event.getItemContainer().getItems();

        int newEss = 0;
        int newSpace = 0;

        // Count ess/space, and change pouch states
        for (Item item : items) {
            switch (item.getId()) {
                case ItemID.BLANKRUNE_HIGH:
                case ItemID.BLANKRUNE_DAEYALT:
                case ItemID.GOTR_GUARDIAN_ESSENCE:
                newEss += 1;
                break;
                case -1:
                newSpace += 1;
                break;
                case ItemID.RCU_POUCH_MEDIUM:
                case ItemID.RCU_POUCH_LARGE:
                case ItemID.RCU_POUCH_GIANT:
                case ItemID.RCU_POUCH_COLOSSAL:
                Pouch pouch = Pouch.forItem(item.getId());
                pouch.degrade(false);
                break;
                case ItemID.RCU_POUCH_MEDIUM_DEGRADE:
                case ItemID.RCU_POUCH_LARGE_DEGRADE:
                case ItemID.RCU_POUCH_GIANT_DEGRADE:
                case ItemID.RCU_POUCH_COLOSSAL_DEGRADE:
                pouch = Pouch.forItem(item.getId());
                pouch.degrade(true);
                break;
            }
        }
        if (items.length < INVENTORY_SIZE) {
            // Pad newSpace for unallocated inventory slots
            newSpace += INVENTORY_SIZE - items.length;
        }

        if (clickedItems.isEmpty()) {
            lastSpace = newSpace;
            lastEssence = newEss;
            return;
        }

        if (lastEssence == -1 || lastSpace == -1) {
            lastSpace = newSpace;
            lastEssence = newEss;
            clickedItems.clear();
            return;
        }

        final int tick = Microbot.getClient().getTickCount();

        int essence = lastEssence;
        int space = lastSpace;

        while (essence != newEss) {
            ClickOperation op = clickedItems.poll();
            if (op == null) {
                break;
            }

            if (tick > op.tick) {
                continue;
            }

            Pouch pouch = op.pouch;

            final boolean fill = op.delta > 0;
            System.out.println(pouch.getRemaining() + " " + pouch.getHolding());
            // How much ess can either be deposited or withdrawn
            final int required = fill ? pouch.getRemaining() : pouch.getHolding();
            // Bound to how much ess or free space we actually have, and optionally negate
            final int essenceGot = op.delta * min(required, fill ? essence : space);

            // if we have enough essence or space to fill or empty the entire pouch, it no
            // longer becomes unknown
            if (pouch.isUnknown() && (fill ? essence : space) >= pouch.getHoldAmount()) {
                pouch.setUnknown(false);
            }

            essence -= essenceGot;
            space += essenceGot;

            pouch.addHolding(essenceGot);
        }

        lastSpace = newSpace;
        lastEssence = newEss;
    }

    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (!isRunning) {
            return;
        }

        int itemId = event.getItemId();

        if (itemId == -1) {
            return;
        }

        final Pouch pouch = Pouch.forItem(itemId);
        if (pouch == null) {
            return;
        }
        final int tick = Microbot.getClient().getTickCount() + 3;
        System.out.println(event.getMenuOption());
        switch (event.getMenuOption().toLowerCase()) {
            case "fill":
                clickedItems.add(new ClickOperation(pouch, tick, 1));
                break;
            case "empty":
                clickedItems.add(new ClickOperation(pouch, tick, -1));
                break;
            case "check":
                checkedPouches.add(new ClickOperation(pouch, tick));
                break;
            case "take":
                // Dropping pouches clears them, so clear when picked up
                pouch.setHolding(0);
                break;
        }
    }
}


