        moveToGodWarsGWD = new ObjectStep(this, ObjectID.GODWARS_ENTRANCE_MULTI, new WorldPoint(2919, 3747, 0),
            "Go down the hole. Bring a rope if this is your first time entering.", combatGear, food);
