        treeGnomeVillage = new QuestRequirement(QuestHelperQuest.TREE_GNOME_VILLAGE, QuestState.FINISHED);
        oneSmallFavour = new QuestRequirement(QuestHelperQuest.ONE_SMALL_FAVOUR, QuestState.IN_PROGRESS);
