    // Zones
    Zone countCheck;
    Zone floorWar;
    Zone floorFamine;
    Zone floorPestilence;
    Zone floorDeath;
    Zone startRoomWar;
    Zone startRoomFamine;
    Zone startRoomPestilence;

    // Steps
    QuestStep talkToCountCheck;
