        theatreP1 = new Zone(new WorldPoint(3638, 3202, 1), new WorldPoint(3646, 3214, 1));
        theatreP2 = new Zone(new WorldPoint(3642, 3214, 2), new WorldPoint(3645, 3224, 2));
