        onQuestion3 = new WidgetTextRequirement(219, 1, 0, "leader");
        onQuestion4 = new WidgetTextRequirement(219, 1, 0, "boatman");
        onQuestion5 = new WidgetTextRequirement(219, 1, 0, "vampyre");
