        talkToMurphy.addDialogStep("Talk about Recipe for Disaster.");
        talkToMurphyAgain = new NpcStep(this, NpcID.MURPHY, new WorldPoint(2664, 3160, 0), "Talk to Murphy again.", fishBowl);
