        ItemRequirement zamorakBrew3 = new ItemRequirement("Zamorak brew(3)", ItemID._3DOSEPOTIONOFZAMORAK);
        ItemRequirement zamorakBrew4 = new ItemRequirement("Zamorak brew(4)", ItemID._4DOSEPOTIONOFZAMORAK);

