        r8 = new Conditions(new VarbitRequirement(VarbitID.SOTE_LIGHT_0_A_8_TO_0_B_8, WHITE), r4);
        r9 = new Conditions(new VarbitRequirement(VarbitID.SOTE_PILLAR_0_B_8_TO_1_B_8, WHITE), r4);

