        // An axe fit for a king
        talkToSantiri = new NpcStep(this, NpcID.DWARF_CITY_SHOP_WEAPONS, new WorldPoint(2828, 10231, 0), "Talk to Santiri.");
        talkToSantiri.addDialogStep("Yes, I'm looking for a particular battleaxe.");
