        inSkavidRoom1 = new ZoneRequirement(skavidRoom1);
        inSkavidRoom2 = new ZoneRequirement(skavidRoom2);
        inSkavidRoom3 = new ZoneRequirement(skavidRoom3);
        inSkavidRoom4 = new ZoneRequirement(skavidRoom4);
