// ----- BaseQuest (net.runelite.client.plugins.microbot.questhelper.logic) -----
public abstract class BaseQuest implements IQuest {

    protected QuestHelperPlugin getQuestHelperPlugin() {
        return (QuestHelperPlugin) Microbot.getPluginManager().getPlugins().stream().filter(x -> x instanceof QuestHelperPlugin).findFirst().orElse(null);
    }
}

// ----- IQuest (net.runelite.client.plugins.microbot.questhelper.logic) -----
public interface IQuest {
    boolean executeCustomLogic();
}

// ----- PiratesTreasure (net.runelite.client.plugins.microbot.questhelper.logic) -----
/**
 * Pirate's Treasure quest custom logic
 */
@Slf4j
public class PiratesTreasure extends BaseQuest {

    public void setMQuestPlugin(QuestHelperPlugin mQuestPlugin) {
        this.mQuestPlugin = mQuestPlugin;
    }

        private QuestHelperPlugin mQuestPlugin;

        public PiratesTreasure() {
        }

        public PiratesTreasure(QuestHelperPlugin mQuestPlugin) {
            this.mQuestPlugin = mQuestPlugin;
        }

    @Override
    public boolean executeCustomLogic() {
        QuestStep questStep = getQuestHelperPlugin().getSelectedQuest().getCurrentStep().getActiveStep();
        if (getQuestHelperPlugin().getSelectedQuest().getQuest().getId() == Quest.PIRATES_TREASURE.getId()) {
            if (questStep.getText().contains("Please open Pirate Treasure's Quest Journal to sync the current quest state.")) {

                Rs2Tab.switchToQuestTab();

                sleep(600, 800);

                directQuestSearch();

                sleep(600, 800);

                Rs2Widget.clickWidget("Pirate's Treasure");

                sleep(600, 800);

                Rs2Widget.clickWidget("Close Floating panel");
                sleep(2000);
                Rs2Widget.clickWidget("Close");

                sleep(2000);

                /* walkTo(3027, 3222, 0);

                if (Rs2Npc.getNpc("Seaman Lorris") != null) {
                Rs2Npc.interact("Seaman Lorris", "Talk-to");
                sleepUntil(Rs2Dialogue::isInDialogue);
                if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                }
                sleep(600, 800);
                if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                }
                sleep(600, 800);
                if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                }
                } */

                return true;
            }
            if (questStep.getText().contains("Right-click fill the rest of the crate with bananas, then talk to Luthas.")) {
                Rs2Walker.walkTo(2917, 3161, 0);
                sleep(2000);
                collectBananas();

                return true;
            }
            if (questStep.getText().contains("Talk to Luthas and tell him you finished filling the crate.")) {
                Rs2Walker.walkTo(2942, 3150, 0);
                sleep(2000);
                Rs2GameObject.interact(2072, "Search", 10);
                sleep(6000);
                if (!mQuestPlugin.fullCrate) {
                collectBananas();
                } else {
                Rs2Npc.interact("Luthas", "Talk-to");
                sleepUntil(Rs2Dialogue::isInDialogue);
                Rs2Dialogue.clickContinue();
                sleep(2000);
                Rs2Dialogue.clickContinue();
                }
                return true;
            }

            if (questStep.getText().contains("Search the crate in the back room of the Port Sarim food shop. Make sure you're wearing your white apron.")) {
                if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                }
                return true;
            }

            if (questStep.getText().contains("Dig in the middle of the cross in Falador Park, and kill the Gardener (level 4) who appears. Once killed, dig again.")) {
                if (!Rs2Inventory.contains(SPADE)) {
                System.out.println("here2");
                Rs2Walker.setTarget(null);
                sleep(1200);
                Rs2Walker.walkTo(2982, 3369, 0);
                sleep(1200);
                Rs2GroundItem.loot(SPADE);
                sleep(1200);
                }

                //to give time to kill the npc (you can actually just run away and run back to dig and it works)
                if (Rs2Player.isInCombat()) {
                sleepUntil(() -> !Rs2Player.isInCombat(), 30000);
                }
                return true;
            }

        }
        return true;
    }

    public static void collectBananas() {
        if (Rs2Inventory.count(BANANA) >= 10) {
            return;
        }

        pickBananasAt(new int[][]{
                {2917, 3161, 0},
                {2920, 3168, 0},
                {2909, 3163, 0}
        });

        if (Rs2Inventory.count(BANANA) >= 10) {
            Rs2Walker.walkTo(2942, 3150, 0);
            sleep(2000);
            Rs2GameObject.interact(2072, "Fill", 10);
            sleep(2000);
        }
    }

    private static void pickBananasAt(int[][] locations) {
        for (int[] location : locations) {
            Rs2Walker.walkTo(location[0], location[1], location[2]);
            sleep(2000);
            pickBananaTree();
        }
    }

    private static void pickBananaTree() {
        for (int i = 0; i < 4; i++) { // 4 picks total
            Rs2GameObject.interact("Banana Tree", "Pick");
            sleep(800, 1500); // Sleep after each click
        }
    }

    private void directQuestSearch() {
        if (openSearchWidget()) {
            sleep(600, 800);
            Rs2Keyboard.typeString("Pirate");
            sleep(800, 1000);
        }
    }

    private boolean openSearchWidget() {
        // Get the widget with accurate coordinates
        int groupId = 26148864 >> 16;
        Widget parentWidget = Microbot.getClient().getWidget(groupId, 0);

        if (parentWidget != null) {
            // From the widget info: RelativeX 161, RelativeY 0, Width 18, Height 17
            // Calculate the exact center point where we need to click
            Point canvasLocation = parentWidget.getCanvasLocation();
            int exactX = canvasLocation.getX() + 161 + 9; // center X
            int exactY = canvasLocation.getY() + 8;       // center Y

            // Create a precise click point directly on the search icon
            Point clickPoint = new Point(exactX, exactY);

            Microbot.log("Clicking search icon at " + clickPoint.getX() + ", " + clickPoint.getY());

            // Create a direct menu entry for clicking the search using the builder-style API
            NewMenuEntry entry = new NewMenuEntry()
                .option("Open")
                .target("Search")
                .identifier(2)
                .type(MenuAction.CC_OP)
                .param0(0)
                .param1(26148864)
                .forceLeftClick(false);

            // Use mouse to click at the exact point
            Microbot.getMouse().click(clickPoint, entry);
            sleep(500, 700);
            return true;
        }
        return false;
    }
}

// ----- QuestRegistry (net.runelite.client.plugins.microbot.questhelper.logic) -----
/**
 * Registry for all quests
 */
public class QuestRegistry {
    private static final Map<Integer, IQuest> QUEST_MAP = new HashMap<>();

    static {
        QUEST_MAP.put(Quest.ROMEO__JULIET.getId(), new RomeoAndJuliet());
        QUEST_MAP.put(Quest.RUNE_MYSTERIES.getId(), new RuneMysteries());
        QUEST_MAP.put(Quest.PIRATES_TREASURE.getId(), new PiratesTreasure());

    }

    /**
     * Get the quest implementation for the given quest id
     * @param questId
     * @return
     */
    public static IQuest getQuest(int questId) {
        IQuest quest = QUEST_MAP.getOrDefault(questId, null);
        return quest;
    }
}

// ----- RomeoAndJuliet (net.runelite.client.plugins.microbot.questhelper.logic) -----
/**
 * Romeo and Juliet quest custom logic
 */
public class RomeoAndJuliet extends BaseQuest {
    @Override
    public boolean executeCustomLogic() {
        QuestStep questStep = getQuestHelperPlugin().getSelectedQuest().getCurrentStep().getActiveStep();
        if (getQuestHelperPlugin().getSelectedQuest().getQuest().getId() == Quest.ROMEO__JULIET.getId()) {
            if (Rs2Dialogue.hasDialogueOptionTitle("Start the Romeo & Juliet quest?")) {
                Rs2Dialogue.keyPressForDialogueOption("Yes.");
                return false;
            }
            if (questStep.getText().contains("Bring the cadava berries to the Apothecary in south east Varrock.")) {
                boolean hasCadavaBerries = fetchCadavaBerries();
                if (!hasCadavaBerries) {
                return false;
                }
            }
        }
        return true;
    }

    private boolean fetchCadavaBerries() {
        if (Rs2Inventory.hasItem(ItemID.CADAVABERRIES)) {
            return true;
        }
        if (Rs2Walker.walkTo(3266, 3374, 0, 10)) {
            Rs2GameObject.interact(new int[] {ObjectID.FAI_VARROCK_CADAVABUSH_2, ObjectID.FAI_VARROCK_CADAVABUSH_1, ObjectID.FAI_VARROCK_CADAVABUSH_0}, "take");
            Rs2Player.waitForWalking();
            Rs2Inventory.waitForInventoryChanges(2000);
        }

        return Rs2Inventory.hasItem(ItemID.CADAVABERRIES);
    }
}

// ----- RuneMysteries (net.runelite.client.plugins.microbot.questhelper.logic) -----
/**
 * Custom logic for RuneMysteries Quest
 */
public class RuneMysteries extends BaseQuest {
    @Override
    public boolean executeCustomLogic() {
        QuestStep questStep = getQuestHelperPlugin().getSelectedQuest().getCurrentStep().getActiveStep();
        if (questStep.getText().get(0).equalsIgnoreCase("Bring the research notes to Sedridor in the Wizard Tower's basement.")) {
            if (!Rs2Inventory.hasItem("notes")) {
                if (Rs2Player.isInCombat()) {
                Microbot.showMessage("You are in combat, please finish the fight before continuing.");
                return false;
                }
                if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                return false;
                }
                var npc = Rs2Npc.getNpc(NpcID.AUBURY_2OP);
                if (new WorldPoint(3253, 3401, 0).distanceTo(Rs2Player.getWorldLocation()) > 3) {
                Rs2Walker.walkTo(3253, 3401, 0, 3);
                } else if (!Rs2Dialogue.isInDialogue()) {
                Rs2Npc.interact(npc, "Talk-to");
                }
                return false;
            }
        }
        try {
            var objectStep = (ObjectStep) questStep;
            if (objectStep.getRequirements() != null && objectStep.getRequirements().stream().findFirst().orElse(null) instanceof ItemRequirement
            && ((ItemRequirement) objectStep.getRequirements().stream().findFirst().get()).getId() == ItemID.AIR_TALISMAN) {
                if (!Rs2Inventory.hasItem(ItemID.AIR_TALISMAN)) {
                if (Rs2Dialogue.hasSelectAnOption()) {
                Rs2Dialogue.keyPressForDialogueOption("What did you want me to do again?");
                return false;
                } else if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                return false;
                }
                var npc = Rs2Npc.getNpc(NpcID.DUKE_OF_LUMBRIDGE);
                if (npc == null) {
                Rs2Walker.walkTo(3209, 3222, 1, 3);
                } else {
                Rs2Npc.interact(npc, "Talk-to");
                }
                return false;
                }
            } else if (Rs2Dialogue.hasDialogueOption("Climb down the stairs.")) {
                Rs2Dialogue.keyPressForDialogueOption("Climb down the stairs.");
                return false;
            }
        } catch (Exception ex) {
            //ignore error
        }
        try {
            var npcStep = (NpcStep) questStep;
            if (npcStep.getRequirements() != null && npcStep.getRequirements().stream().findFirst().orElse(null) instanceof ItemRequirement) {
                ItemRequirement itemRequirement = (ItemRequirement) npcStep.getRequirements().stream().findFirst().get();
                if (!Rs2Inventory.hasItem(itemRequirement.getId())) {
                if (Rs2Dialogue.isInDialogue()) {
                Rs2Dialogue.clickContinue();
                return false;
                }
                var npc = Rs2Npc.getNpc(NpcID.HEAD_WIZARD_1OP);
                if (new WorldPoint(3105, 9571, 0).distanceTo(Rs2Player.getWorldLocation()) > 3) {
                Rs2Walker.walkTo(3105, 9571, 0, 3);
                } else if (!Rs2Dialogue.isInDialogue()) {
                Rs2Npc.interact(npc, "Talk-to");
                }
                return false;
                }
            } else if (Rs2Dialogue.hasDialogueOption("Anything useful in that package I gave you?")) {
                Rs2Dialogue.keyPressForDialogueOption("Anything useful in that package I gave you?");
                return false;
            }
        } catch (Exception ex) {
            //ignore error
        }
        if (Rs2Dialogue.hasDialogueOption("Go ahead.")) {
            Rs2Dialogue.keyPressForDialogueOption("Go ahead.");
            return false;
        }
        return true;
    }
}


