/**
 * This class is useful for dealing with the world map, where the viewed area is relevant to the placement of a {@link WorldPoint}.
 */
@Value
public class WorldPointWithWorldMapArea
{
    WorldPoint worldPoint;

    WorldMapArea worldMapArea;
}


// ========== Package: net.runelite.client.plugins.microbot.shortestpath ==========

// ----- DebugOverlayPanel (net.runelite.client.plugins.microbot.shortestpath) -----
public class DebugOverlayPanel extends OverlayPanel {
    private final ShortestPathPlugin plugin;
    private final SeparatorLine separator;

    @Inject
    public DebugOverlayPanel(ShortestPathPlugin plugin) {
        super(plugin);
        this.plugin = plugin;

        separator = new SeparatorLine();
        separator.setColor(new Color(0, true)); // Invisible color

        setPosition(OverlayPosition.TOP_LEFT);
    }

    private LineComponent makeLine(String left, String right) {
        return LineComponent.builder()
                .left(left)
                .right(right)
                .build();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Pathfinder pathfinder = ShortestPathPlugin.getPathfinder();
        Pathfinder.PathfinderStats stats;
        if (pathfinder == null || !pathfinder.isDone() || (stats = pathfinder.getStats()) == null) {
            return null;
        }

        List<LayoutableRenderableEntity> components = panelComponent.getChildren();

        components.add(
                TitleComponent.builder()
                .text("Shortest Path Debug")
                .color(Color.ORANGE)
                .build()
        );

        components.add(separator);

        String pathLength = Integer.toString(pathfinder.getPath().size());
        components.add(makeLine("Path Length:", pathLength));

        components.add(separator);

        String nodes = Integer.toString(stats.getNodesChecked());
        components.add(makeLine("Nodes:", nodes));

        String transports = Integer.toString(stats.getTransportsChecked());
        components.add(makeLine("Transports:", transports));

        String totalNodes = Integer.toString(stats.getTotalNodesChecked());
        components.add(makeLine("Total:", totalNodes));

        components.add(separator);

        double milliTime = stats.getElapsedTimeNanos() / 1000000.0;
        String time = String.format("%.2fms", milliTime);
        components.add(makeLine("Time:", time));

        return super.render(graphics);
    }

    @Setter
    private static class SeparatorLine implements LayoutableRenderableEntity {
        private Color color = Color.GRAY;
        private Point preferredLocation = new Point();
        private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 4);

        @Getter
        private final Rectangle bounds = new Rectangle();

        @Override
        public Dimension render(Graphics2D graphics) {
            final int separatorX = preferredLocation.x;
            final int separatorY = preferredLocation.y + 4;
            final int width = preferredSize.width;
            final int height = Math.max(preferredSize.height, 2);

            // Draw bar
            if (color != null && color.getAlpha() != 0) {
                graphics.setColor(color);
                graphics.fillRect(separatorX, separatorY, width, height);
            }

            final Dimension dimension = new Dimension(width, height + 4);
            bounds.setLocation(preferredLocation);
            bounds.setSize(dimension);

            return dimension;
        }
    }
}

// ----- ETAOverlayPanel (net.runelite.client.plugins.microbot.shortestpath) -----
public class ETAOverlayPanel extends OverlayPanel {

    private final ShortestPathPlugin plugin;

    @Inject
    ETAOverlayPanel(ShortestPathPlugin plugin) {
        this.plugin = plugin;
        setPosition(OverlayPosition.CANVAS_TOP_RIGHT);
        setNaughty();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        try {
            panelComponent.setBackgroundColor(new Color(0, 0, 0, 0));
            panelComponent.setPreferredSize(new Dimension(160, 100));

            if (ShortestPathPlugin.getPathfinder() != null && ShortestPathPlugin.getPathfinder().getPath() != null) {
                List<WorldPoint> path = ShortestPathPlugin.getPathfinder().getPath();
                WorldPoint playerLocation = Rs2Player.getWorldLocation();

                int progressIndex = findClosestPointIndex(playerLocation, path);

                int remainingPathLength = path.size() - progressIndex;

                String remainingTime = RunEnergyPlugin.calculateTravelTime(remainingPathLength, plugin.getConfig().showInSeconds());

                panelComponent.getChildren().add(LineComponent.builder()
                .left("Est. Time till Arrival:")
                .right(remainingTime)
                .build());
            } else {
                if (!panelComponent.getChildren().isEmpty()) {
                panelComponent.getChildren().clear();
                }
            }
        } catch (Exception ex) {
            System.out.println("Error in render: " + ex.getMessage());
        }
        return super.render(graphics);
    }

    private int findClosestPointIndex(WorldPoint playerLocation, List<WorldPoint> path) {
        return IntStream.range(0, path.size())
                .boxed()
                .min(Comparator.comparingInt(i -> playerLocation.distanceTo(path.get(i))))
                .orElse(0);
    }
}

// ----- MinimapOverlay (net.runelite.client.plugins.microbot.shortestpath) -----
public class MinimapOverlay extends Overlay
{
    @Inject
    MinimapOverlay(ShortestPathPlugin plugin)
    {
        super(plugin);
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGHEST);
        drawAfterInterface(InterfaceID.TOPLEVEL_DISPLAY);
        setNaughty();
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {

        Shape minimapClip = Rs2MiniMap.getMinimapClipArea();

        Widget minimapWidget = Rs2MiniMap.getMinimapDrawWidget();

        if (minimapWidget != null)
        {
            graphics.setColor(Color.RED);
            graphics.draw(minimapWidget.getBounds());
        }

        if (minimapClip != null)
        {
            graphics.setColor(Color.GREEN);
            graphics.draw(minimapClip);
        }

        return null;
    }
}

// ----- PathMapOverlay (net.runelite.client.plugins.microbot.shortestpath) -----
public class PathMapOverlay extends Overlay {
    private final Client client;
    private final ShortestPathPlugin plugin;

    @Inject
    private WorldMapOverlay worldMapOverlay;

    @Inject
    private PathMapOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_LOW);
        setLayer(OverlayLayer.MANUAL);
        drawAfterLayer(ComponentID.WORLD_MAP_MAPVIEW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.drawMap) {
            return null;
        }

        if (client.getWidget(ComponentID.WORLD_MAP_MAPVIEW) == null) {
            return null;
        }

        Area worldMapClipArea = getWorldMapClipArea(client.getWidget(ComponentID.WORLD_MAP_MAPVIEW).getBounds());
        graphics.setClip(worldMapClipArea);

        if (plugin.drawCollisionMap) {
            graphics.setColor(plugin.colourCollisionMap);
            Rectangle extent = getWorldMapExtent(client.getWidget(ComponentID.WORLD_MAP_MAPVIEW).getBounds());
            final CollisionMap map = plugin.getMap();
            final int z = client.getPlane();
            for (int x = extent.x; x < (extent.x + extent.width + 1); x++) {
                for (int y = extent.y - extent.height; y < (extent.y + 1); y++) {
                if (map.isBlocked(x, y, z)) {
                drawOnMap(graphics, new WorldPoint(x, y, z), false);
                }
                }
            }
        }

        if (plugin.drawTransports) {
            graphics.setColor(Color.WHITE);
            if (ShortestPathPlugin.getTransports() == null) return null;
            if (ShortestPathPlugin.getPathfinder() == null || !ShortestPathPlugin.getPathfinder().isDone()) return null;
            for (WorldPoint a : ShortestPathPlugin.getTransports().keySet()) {
                Point mapA = worldMapOverlay.mapWorldPointToGraphicsPoint(a);
                if (mapA == null || !worldMapClipArea.contains(mapA.getX(), mapA.getY())) {
                continue;
                }

                for (Transport b : ShortestPathPlugin.getTransports().getOrDefault(a, new HashSet<>())) {
                Point mapB = worldMapOverlay.mapWorldPointToGraphicsPoint(b.getDestination());
                if (mapB == null || !worldMapClipArea.contains(mapB.getX(), mapB.getY())) {
                continue;
                }

                graphics.drawLine(mapA.getX(), mapA.getY(), mapB.getX(), mapB.getY());
                }
            }
        }

        if (ShortestPathPlugin.getPathfinder() != null) {
            Color colour = ShortestPathPlugin.getPathfinder().isDone() ? plugin.colourPath : plugin.colourPathCalculating;
            List<WorldPoint> path = ShortestPathPlugin.getPathfinder().getPath();
            for (int i = 0; i < path.size(); i++) {
                graphics.setColor(colour);
                WorldPoint point = path.get(i);
                WorldPoint last = (i > 0) ? path.get(i - 1) : point;
                if (point.distanceTo(last) > 1) {
                drawOnMap(graphics, last, point, true);
                }
                drawOnMap(graphics, point, true);
            }
        }

        return null;
    }

    private void drawOnMap(Graphics2D graphics, WorldPoint point, boolean checkHover) {
        drawOnMap(graphics, point, point.dx(1).dy(-1), checkHover);
    }

    private void drawOnMap(Graphics2D graphics, WorldPoint point, WorldPoint offset, boolean checkHover) {
        Point start = plugin.mapWorldPointToGraphicsPoint(point);
        Point end = plugin.mapWorldPointToGraphicsPoint(offset);

        if (start == null || end == null) {
            return;
        }

        int x = start.getX();
        int y = start.getY();
        final int width = end.getX() - x;
        final int height = end.getY() - y;
        x -= width / 2;
        y -= height / 2;

        if (point.distanceTo(offset) > 1) {
            graphics.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0));
            graphics.drawLine(start.getX(), start.getY(), end.getX(), end.getY());
        } else {
            Point cursorPos = client.getMouseCanvasPosition();
            if (checkHover &&
                cursorPos.getX() >= x && cursorPos.getX() <= (end.getX() - width / 2) &&
                cursorPos.getY() >= y && cursorPos.getY() <= (end.getY() - width / 2)) {
                graphics.setColor(graphics.getColor().darker());
            }
            graphics.fillRect(x, y, width, height);
        }
    }

    private Area getWorldMapClipArea(Rectangle baseRectangle) {
        final Widget overview = client.getWidget(ComponentID.WORLD_MAP_OVERVIEW_MAP);
        final Widget surfaceSelector = client.getWidget(ComponentID.WORLD_MAP_SURFACE_SELECTOR);

        Area clipArea = new Area(baseRectangle);

        if (overview != null && !overview.isHidden()) {
            clipArea.subtract(new Area(overview.getBounds()));
        }

        if (surfaceSelector != null && !surfaceSelector.isHidden()) {
            clipArea.subtract(new Area(surfaceSelector.getBounds()));
        }

        return clipArea;
    }

    private Rectangle getWorldMapExtent(Rectangle baseRectangle) {
        WorldPoint topLeft = plugin.calculateMapPoint(new Point(baseRectangle.x, baseRectangle.y));
        WorldPoint bottomRight = plugin.calculateMapPoint(
                new Point(baseRectangle.x + baseRectangle.width, baseRectangle.y + baseRectangle.height));
        return new Rectangle(topLeft.getX(), topLeft.getY(), bottomRight.getX() - topLeft.getX(), topLeft.getY() - bottomRight.getY());
    }
}

// ----- PathMapTooltipOverlay (net.runelite.client.plugins.microbot.shortestpath) -----
public class PathMapTooltipOverlay extends Overlay {
    private static final int TOOLTIP_OFFSET_HEIGHT = 25;
    private static final int TOOLTIP_OFFSET_WIDTH = 15;
    private static final int TOOLTIP_PADDING_HEIGHT = 1;
    private static final int TOOLTIP_PADDING_WIDTH = 2;
    private static final int TOOLTIP_TEXT_OFFSET_HEIGHT = -2;

    private final Client client;
    private final ShortestPathPlugin plugin;

    @Inject
    private PathMapTooltipOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_HIGHEST);
        setLayer(OverlayLayer.MANUAL);
        drawAfterInterface(InterfaceID.WORLD_MAP);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.drawMap || client.getWidget(ComponentID.WORLD_MAP_MAPVIEW) == null) {
            return null;
        }

        if (ShortestPathPlugin.getPathfinder() != null && ShortestPathPlugin.getPathfinder().isDone()) {
            List<WorldPoint> path = ShortestPathPlugin.getPathfinder().getPath();
            Point cursorPos = client.getMouseCanvasPosition();
            for (int i = 0; i < path.size(); i++) {
                WorldPoint nextPoint = null;
                if (path.size() > i + 1) {
                nextPoint = path.get(i + 1);
                }
                if (drawTooltip(graphics, cursorPos, path.get(i), nextPoint, i + 1)) {
                return null;
                }
            }
        }

        return null;
    }

    private boolean drawTooltip(Graphics2D graphics, Point cursorPos, WorldPoint point, @Nullable WorldPoint nextPoint, int n) {
        Point start = plugin.mapWorldPointToGraphicsPoint(point);
        Point end = plugin.mapWorldPointToGraphicsPoint(point.dx(1).dy(-1));

        if (start == null || end == null) {
            return false;
        }

        int width = end.getX() - start.getX();

        if (cursorPos.getX() < (start.getX() - width / 2) || cursorPos.getX() > (end.getX() - width / 2) ||
                cursorPos.getY() < (start.getY() - width / 2) || cursorPos.getY() > (end.getY() - width / 2)) {
            return false;
        }

        List<String> rows = new ArrayList<>(Arrays.asList("Shortest path:", "Step " + n + " of " + ShortestPathPlugin.getPathfinder().getPath().size()));
        if (nextPoint != null) {
            for (Transport transport : ShortestPathPlugin.getTransports().getOrDefault(point, new HashSet<>())) {
                if (nextPoint.equals(transport.getDestination())
                && transport.getDisplayInfo() != null && !transport.getDisplayInfo().isEmpty()) {
                rows.add(transport.getDisplayInfo());
                break;
                }
            }
        }

        graphics.setFont(FontManager.getRunescapeFont());
        FontMetrics fm = graphics.getFontMetrics();
        int tooltipHeight = fm.getHeight();
        int tooltipWidth = rows.stream().map(fm::stringWidth).max(Integer::compareTo).get();

        int clippedHeight = tooltipHeight * rows.size() + TOOLTIP_PADDING_HEIGHT * 2;
        int clippedWidth = tooltipWidth + TOOLTIP_PADDING_WIDTH * 2;

        Rectangle worldMapBounds = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW).getBounds();
        int worldMapRightBoundary = worldMapBounds.width + worldMapBounds.x;
        int worldMapBottomBoundary = worldMapBounds.height + worldMapBounds.y;

        int drawPointX = start.getX() + TOOLTIP_OFFSET_WIDTH;
        int drawPointY = start.getY();
        if (drawPointX + clippedWidth > worldMapRightBoundary) {
            drawPointX = worldMapRightBoundary - clippedWidth;
        }
        if (drawPointY + clippedHeight > worldMapBottomBoundary) {
            drawPointY = start.getY() - clippedHeight;
        }
        drawPointY += TOOLTIP_OFFSET_HEIGHT;

        Rectangle tooltipRect = new Rectangle(
                drawPointX - TOOLTIP_PADDING_WIDTH,
                drawPointY - TOOLTIP_PADDING_HEIGHT,
                clippedWidth,
                clippedHeight);

        graphics.setColor(JagexColors.TOOLTIP_BACKGROUND);
        graphics.fillRect(tooltipRect.x, tooltipRect.y, tooltipRect.width, tooltipRect.height);

        graphics.setColor(JagexColors.TOOLTIP_BORDER);
        graphics.drawRect(tooltipRect.x, tooltipRect.y, tooltipRect.width, tooltipRect.height);

        graphics.setColor(JagexColors.TOOLTIP_TEXT);
        for (int i = 0; i < rows.size(); i++) {
            graphics.drawString(rows.get(i), drawPointX, drawPointY + TOOLTIP_TEXT_OFFSET_HEIGHT + (i + 1) * tooltipHeight);
        }

        return true;
    }
}

// ----- PathMinimapOverlay (net.runelite.client.plugins.microbot.shortestpath) -----
public class PathMinimapOverlay extends Overlay {
    private static final int TILE_WIDTH = 2;
    private static final int TILE_HEIGHT = 2;

    private final Client client;
    private final ShortestPathPlugin plugin;
    private final ShortestPathConfig config;

    @Inject
    private PathMinimapOverlay(Client client, ShortestPathPlugin plugin, ShortestPathConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.drawMinimap) {
            return null;
        }

        final Pathfinder pathfinder = ShortestPathPlugin.getPathfinder();
        if (pathfinder == null || !pathfinder.isDone()) return null;

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        graphics.setClip(plugin.getMinimapClipArea());

        List<WorldPoint> pathPoints = pathfinder.getPath();
        Color pathColor = pathfinder.isDone() ? plugin.colourPath : plugin.colourPathCalculating;
        for (WorldPoint pathPoint : pathPoints) {
            if (pathPoint.getPlane() != client.getPlane()) {
                continue;
            }

            drawOnMinimap(graphics, pathPoint, pathColor);
        }

        return null;
    }

    private void drawOnMinimap(Graphics2D graphics, WorldPoint location, Color color) {
        for (WorldPoint point : WorldPoint.toLocalInstance(client, location)) {
            LocalPoint lp = LocalPoint.fromWorld(client, point);

            if (lp == null) {
                continue;
            }

            Point posOnMinimap = Perspective.localToMinimap(client, lp);

            if (posOnMinimap == null) {
                continue;
            }

            renderMinimapRect(client, graphics, posOnMinimap, TILE_WIDTH, TILE_HEIGHT, color);
        }
    }

    public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, int width, int height, Color color) {
        double angle = client.getCameraYawTarget() * Math.PI / 1024.0d;

        graphics.setColor(color);
        graphics.rotate(angle, center.getX(), center.getY());
        graphics.fillRect(center.getX() - width / 2, center.getY() - height / 2, width, height);
        graphics.rotate(-angle, center.getX(), center.getY());
    }
}

// ----- PathTileOverlay (net.runelite.client.plugins.microbot.shortestpath) -----
public class PathTileOverlay extends Overlay {
    private final Client client;
    private final ShortestPathPlugin plugin;
    private static final int TRANSPORT_LABEL_GAP = 3;

    @Inject
    public PathTileOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_LOW);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    private void renderTransports(Graphics2D graphics) {
        if (plugin == null) return;
        if (ShortestPathPlugin.getTransports() == null) return;
        if (ShortestPathPlugin.getPathfinderFuture() == null || !ShortestPathPlugin.getPathfinderFuture().isDone()) return;
        for (WorldPoint a : ShortestPathPlugin.getTransports().keySet()) {
            drawTile(graphics, a, plugin.colourTransports, -1, true);

            Point ca = tileCenter(a);

            if (ca == null) {
                continue;
            }

            StringBuilder s = new StringBuilder();
            for (Transport b : ShortestPathPlugin.getTransports().getOrDefault(a, new HashSet<>())) {
                for (WorldPoint destination : WorldPoint.toLocalInstance(client, b.getDestination())) {
                Point cb = tileCenter(destination);
                if (cb != null) {
                graphics.drawLine(ca.getX(), ca.getY(), cb.getX(), cb.getY());
                }
                if (destination.getPlane() > a.getPlane()) {
                s.append("+");
                } else if (destination.getPlane() < a.getPlane()) {
                s.append("-");
                } else {
                s.append("=");
                }
                }
            }
            graphics.setColor(Color.WHITE);
            graphics.drawString(s.toString(), ca.getX(), ca.getY());
        }
    }

    private void renderCollisionMap(Graphics2D graphics) {
        CollisionMap map = plugin.getMap();
        for (Tile[] row : client.getScene().getTiles()[client.getPlane()]) {
            for (Tile tile : row) {
                if (tile == null) {
                continue;
                }

                Polygon tilePolygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());

                if (tilePolygon == null) {
                continue;
                }

                WorldPoint location = client.isInInstancedRegion() ?
                WorldPoint.fromLocalInstance(client, tile.getLocalLocation()) : tile.getWorldLocation();
                int x = location.getX();
                int y = location.getY();
                int z = location.getPlane();

                String s = (!map.n(x, y, z) ? "n" : "") +
                (!map.s(x, y, z) ? "s" : "") +
                (!map.e(x, y, z) ? "e" : "") +
                (!map.w(x, y, z) ? "w" : "");

                if (map.isBlocked(x, y, z)) {
                graphics.setColor(plugin.colourCollisionMap);
                graphics.fill(tilePolygon);
                }
                if (!s.isEmpty() && !s.equals("nsew")) {
                graphics.setColor(Color.WHITE);
                int stringX = (int) (tilePolygon.getBounds().getCenterX() - graphics.getFontMetrics().getStringBounds(s, graphics).getWidth() / 2);
                int stringY = (int) tilePolygon.getBounds().getCenterY();
                graphics.drawString(s, stringX, stringY);
                }
            }
        }
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.drawTransports) {
            this.renderTransports(graphics);
        }

        if (plugin.drawCollisionMap) {
            this.renderCollisionMap(graphics);
        }

        final Pathfinder pathfinder = ShortestPathPlugin.getPathfinder();
        if (plugin.drawTiles && pathfinder != null && pathfinder.isDone()) {
            final List<WorldPoint> path = pathfinder.getPath();

            int counter = 0;
            if (TileStyle.LINES.equals(plugin.pathStyle)) {
                for (int i = 1; i < path.size(); i++) {
                float step = i / (float) path.size();
                Color newColor = generateGradient(step);
                newColor = new Color(newColor.getRed(), newColor.getGreen(), newColor.getBlue(), 75);
                drawLine(graphics, path.get(i - 1), path.get(i), newColor, 1 + counter++);
                drawTransportInfo(graphics, path.get(i - 1), path.get(i));
                }
            } else {
                boolean showTiles = TileStyle.TILES.equals(plugin.pathStyle);
                for (int i = 0; i < path.size(); i++) {
                float step = i / (float) path.size();
                Color newColor = generateGradient(step);
                newColor = new Color(newColor.getRed(), newColor.getGreen(), newColor.getBlue(), 75);
                drawTile(graphics, path.get(i), newColor, counter++, showTiles);
                drawTransportInfo(graphics, path.get(i), (i + 1 == path.size()) ? null : path.get(i + 1));
                }
            }
        }

        return null;
    }

    private Point tileCenter(WorldPoint b) {
        if (b.getPlane() != client.getPlane()) {
            return null;
        }

        LocalPoint lp = LocalPoint.fromWorld(client, b);
        if (lp == null) {
            return null;
        }

        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly == null) {
            return null;
        }

        int cx = poly.getBounds().x + poly.getBounds().width / 2;
        int cy = poly.getBounds().y + poly.getBounds().height / 2;
        return new Point(cx, cy);
    }

    private void drawTile(Graphics2D graphics, WorldPoint location, Color color, int counter, boolean draw) {
        for (WorldPoint point : WorldPoint.toLocalInstance(client, location)) {
            if (point.getPlane() != client.getPlane()) {
                continue;
            }

            LocalPoint lp = LocalPoint.fromWorld(client, point);
            if (lp == null) {
                continue;
            }

            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null) {
                continue;
            }

            if (draw) {
                graphics.setColor(color);
                graphics.fill(poly);
            }

            drawCounter(graphics, poly.getBounds().getCenterX(), poly.getBounds().getCenterY(), counter);
        }
    }

    private void drawLine(Graphics2D graphics, WorldPoint startLoc, WorldPoint endLoc, Color color, int counter) {
        Collection<WorldPoint> starts = WorldPoint.toLocalInstance(client, startLoc);
        Collection<WorldPoint> ends = WorldPoint.toLocalInstance(client, endLoc);

        if (starts.isEmpty() || ends.isEmpty()) {
            return;
        }

        WorldPoint start = starts.iterator().next();
        WorldPoint end = ends.iterator().next();

        final int z = client.getPlane();
        if (start.getPlane() != z) {
            return;
        }

        LocalPoint lpStart = LocalPoint.fromWorld(client, start);
        LocalPoint lpEnd = LocalPoint.fromWorld(client, end);

        if (lpStart == null || lpEnd == null) {
            return;
        }

        final int startHeight = Perspective.getTileHeight(client, lpStart, z);
        final int endHeight = Perspective.getTileHeight(client, lpEnd, z);

        Point p1 = Perspective.localToCanvas(client, lpStart.getX(), lpStart.getY(), startHeight);
        Point p2 = Perspective.localToCanvas(client, lpEnd.getX(), lpEnd.getY(), endHeight);

        if (p1 == null || p2 == null) {
            return;
        }

        Line2D.Double line = new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY());

        graphics.setColor(color);
        graphics.setStroke(new BasicStroke(4));
        graphics.draw(line);

        if (counter == 1) {
            drawCounter(graphics, p1.getX(), p1.getY(), 0);
        }
        drawCounter(graphics, p2.getX(), p2.getY(), counter);
    }

    private void drawCounter(Graphics2D graphics, double x, double y, int counter) {
        if (ShortestPathPlugin.getPathfinder() == null) return;
        if (counter >= 0 && !TileCounter.DISABLED.equals(plugin.showTileCounter)) {
            int n = plugin.tileCounterStep > 0 ? plugin.tileCounterStep : 1;
            int s = ShortestPathPlugin.getPathfinder().getPath().size();
            if ((counter % n != 0) && (s != (counter + 1))) {
                return;
            }
            if (TileCounter.REMAINING.equals(plugin.showTileCounter)) {
                counter = s - counter - 1;
            }
            if (n > 1 && counter == 0) {
                return;
            }
            String counterText = Integer.toString(counter);
            graphics.setColor(plugin.colourText);
            graphics.drawString(
                counterText,
                (int) (x - graphics.getFontMetrics().getStringBounds(counterText, graphics).getWidth() / 2), (int) y);
        }
    }

    private void drawTransportInfo(Graphics2D graphics, WorldPoint location, WorldPoint locationEnd) {
        if (locationEnd == null || !plugin.showTransportInfo) {
            return;
        }
        for (WorldPoint point : WorldPoint.toLocalInstance(client, location)) {
            for (WorldPoint pointEnd : WorldPoint.toLocalInstance(client, locationEnd))
            {
                if (point.getPlane() != client.getPlane()) {
                continue;
                }

                int vertical_offset = 0;
                for (Transport transport : ShortestPathPlugin.getTransports().getOrDefault(point, new HashSet<>())) {
                if (pointEnd == null || !pointEnd.equals(transport.getDestination())) {
                continue;
                }

                String text = transport.getDisplayInfo();
                if (text == null || text.isEmpty()) {
                continue;
                }

                LocalPoint lp = LocalPoint.fromWorld(client, point);
                if (lp == null) {
                continue;
                }

                Point p = Perspective.localToCanvas(client, lp, client.getPlane());
                if (p == null) {
                continue;
                }

                Rectangle2D textBounds = graphics.getFontMetrics().getStringBounds(text, graphics);
                double height = textBounds.getHeight();
                int x = (int) (p.getX() - textBounds.getWidth() / 2);
                int y = (int) (p.getY() - height) - (vertical_offset);
                graphics.setColor(Color.BLACK);
                graphics.drawString(text, x + 1, y + 1);
                graphics.setColor(plugin.colourText);
                graphics.drawString(text, x, y);

                vertical_offset += (int) height + TRANSPORT_LABEL_GAP;
                }
            }
        }
    }

    public static Color generateGradient(float step) {
        if (step < 0) {
            step = 0;
        } else if (step > 1) {
            step = 1;
        }

        float[] startComponents = Color.RED.getRGBColorComponents(null);
        float[] endComponents = Color.GREEN.getRGBColorComponents(null);

        float[] interpolatedComponents = new float[3];

        for (int j = 0; j < 3; j++) {
            interpolatedComponents[j] = startComponents[j] + step * (endComponents[j] - startComponents[j]);
        }

        return new Color(interpolatedComponents[0], interpolatedComponents[1], interpolatedComponents[2]);
    }
}

// ----- PohPanel (net.runelite.client.plugins.microbot.shortestpath) -----
public class PohPanel extends PluginPanel {

    private EnumListPanel<PohPortal> portalPanel;
    private EnumListPanel<NexusPortal> nexusPanel;
    private CheckboxPanel checkboxPanel;
    private JewelleryBoxPanel jewelleryBoxPanel;
    private ExitTilePanel tilePanel;

    private JButton detectButton;
    private JScrollPane mainScrollPane;

    private ShortestPathConfig config;
    public static PohPanel instance;

    public PohPanel(ShortestPathConfig config) {
        super(false);
        instance = this;
        this.config = config;
        setLayout(new BorderLayout(8, 8));

        setPreferredSize(null); // Remove any fixed preferred size
        setMaximumSize(null);   // Remove any fixed maximum size

        // Create scrollable content
        mainScrollPane = createMainScrollPane();
        add(mainScrollPane, BorderLayout.CENTER);
        add(buildTopBar(), BorderLayout.SOUTH);
    }

    /**
     * Creates and configures the main scroll pane containing all the content panels.
     *
     * @return A properly configured JScrollPane with all content panels
     */
    private JScrollPane createMainScrollPane() {
        JPanel contentPanel = buildContent();

        JScrollPane scrollPane = new JScrollPane(contentPanel);

        // Configure scroll policies
        scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);

        // Remove default border for cleaner look
        scrollPane.setBorder(BorderFactory.createEmptyBorder());

        // Set background to match the content
        scrollPane.getViewport().setBackground(contentPanel.getBackground());

        // Configure scroll increment for smoother scrolling
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.getVerticalScrollBar().setBlockIncrement(64);

        // Let it fill available space - don't set fixed sizes
        scrollPane.setMinimumSize(new Dimension(120, 0));

        return scrollPane;
    }

    private JPanel buildContent() {
        JPanel root = new JPanel(new GridBagLayout());
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.weightx = 1.0;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.anchor = GridBagConstraints.NORTHWEST;
        gbc.insets.set(4, 4, 4, 4);

        // Portals list
        gbc.gridy = 0;
        portalPanel = new EnumListPanel<>(PohPortal.class, "Portal Room");
        root.add(portalPanel, gbc);

        // Nexus panel
        gbc.gridy++;
        nexusPanel = new EnumListPanel<>(NexusPortal.class, "Nexus Teleport");
        root.add(nexusPanel, gbc);

        // Booleans section
        gbc.gridy++;
        checkboxPanel = new CheckboxPanel();
        root.add(checkboxPanel, gbc);

        // Dropdowns section
        gbc.gridy++;
        jewelleryBoxPanel = new JewelleryBoxPanel();
        root.add(jewelleryBoxPanel, gbc);

        // Tile section
        gbc.gridy++;
        tilePanel = new ExitTilePanel();
        root.add(tilePanel, gbc);

        // Add a filler component to push content to the top and allow proper stretching
        gbc.gridy++;
        gbc.weighty = 1.0; // This is crucial - it allows vertical expansion
        gbc.fill = GridBagConstraints.BOTH;
        JPanel filler = new JPanel();
        filler.setOpaque(false);
        root.add(filler, gbc);

        return root;
    }

    private JButton buildTopBar() {
        detectButton = new JButton("Detect available POH teleports");
        detectButton.addActionListener(e -> detectPortalsFromPOH());

        return detectButton;
    }

    private void detectPortalsFromPOH() {
        if (!PohTeleports.isInHouse()) {
            Microbot.log("Please make sure you are in the POH first!");
            return;
        }
        detectButton.setEnabled(false);
        detectButton.setText("Detecting...");
        checkboxPanel.detectPohFacilities();
        portalPanel.setAll(PohPortal.findPortalsInPoh());
        nexusPanel.setAll(NexusPortal.getAvailableTeleports());
        jewelleryBoxPanel.detectJewelleryBox();
        tilePanel.detectTile();
        detectButton.setEnabled(true);
        detectButton.setText("Detect available POH teleports");
    }

    /**
     * Retrieves a map of transports that take the player to the Player-Owned House (POH).
     * This includes teleports and the external portal location of the house.
     *
     *
     * @return A map where the key is the `WorldPoint` representing the origin of the transport
     *         and the value is a set of `Transport` instances representing the available
     *         methods of transportation to the inside of PoH.
     */
    public static Map<WorldPoint, Set<Transport>> getTransportsToPoh() {
        HouseLocation location = HouseLocation.getHouseLocation();
        Map<WorldPoint, Set<Transport>> transportMap = new HashMap<>();
        if (location == null || instance == null) return transportMap;
        WorldPoint exitPortal = instance.tilePanel.getTile();
        if (exitPortal == null) {
            return transportMap;
        }
        WorldPoint outsidePoint = location.getPortalLocation();

        transportMap.put(null, Set.of(
                new Transport(exitPortal, "Construction cape: Tele to POH", TransportType.TELEPORTATION_ITEM, true, 19, Set.of(Set.of(9789), Set.of(9790))),
                new Transport(exitPortal, "Teleport to House", TransportType.TELEPORTATION_SPELL, true, 19, Map.of(Skill.MAGIC, 40)),
                new Transport(exitPortal, "Teleport to House tablet: Inside", TransportType.TELEPORTATION_ITEM, true, 19, Set.of(Set.of(8013)))
        ));
        transportMap.put(outsidePoint, Set.of(
                new Transport(outsidePoint, exitPortal, location.name() + " -> PoH", TransportType.TELEPORTATION_PORTAL, true, "Home", "Portal", location.getPortalId())
        ));
        return transportMap;
    }

    /**
     * Creates a Set with all available PoH transports directly extracted from cached data
     * Excludes things like Fairy rings and spirit trees as they are based on existing data
     *
     * @return allTransports map with all cached PoH transports added in
     */
    public static Map<WorldPoint, Set<Transport>> getAvailableTransports(Map<WorldPoint, Set<Transport>> allTransports) {
        if (instance == null) return allTransports;
        Set<PohTeleport> pohTeleports = new HashSet<>();
        Map<WorldPoint, Set<Transport>> pohTransports = new HashMap<>();
        WorldPoint exitPortal = instance.tilePanel.getTile();
        if (exitPortal == null) {
            Microbot.log("Failed to load exit portal config");
            return allTransports;
        }

        pohTeleports.addAll(instance.checkboxPanel.getTeleports());
        pohTeleports.addAll(instance.portalPanel.getTeleports());
        pohTeleports.addAll(instance.nexusPanel.getTeleports());
        pohTeleports.addAll(instance.jewelleryBoxPanel.getTeleports());

        if (instance.checkboxPanel.fairyRingCb.isSelected()) {
            Map<WorldPoint, Set<Transport>> fairyRings = createFairyRingMap(exitPortal, allTransports);
            for (var entry : fairyRings.entrySet()) {
                pohTransports
                .computeIfAbsent(entry.getKey(), k -> new HashSet<>())
                .addAll(entry.getValue());
            }
        }
        if (instance.checkboxPanel.spiritTreeCb.isSelected()) {
            Map<WorldPoint, Set<Transport>> spiritTrees = createSpiritTreeMap(exitPortal, allTransports);
            for (var entry : spiritTrees.entrySet()) {
                pohTransports
                .computeIfAbsent(entry.getKey(), k -> new HashSet<>())
                .addAll(entry.getValue());
            }
        }
        pohTransports.computeIfAbsent(exitPortal, p -> new HashSet<>()).addAll(pohTeleports.stream().map(
                t -> new PohTransport(exitPortal, t)
        ).collect(Collectors.toList()));

        return pohTransports;
    }

    /**
     * Connecting the PoH Fairy ring to all other fairy rings and vise versa
     *
     * @param pohFairyRing  position of the PoH fairy ring (exitPortal until mapping inside Poh)
     * @param transportsMap map from which currently present fairy rings are found
     * @return new map with PoH fairy rings transports added
     */
    public static Map<WorldPoint, Set<Transport>> createFairyRingMap(
            WorldPoint pohFairyRing,
            Map<WorldPoint, Set<Transport>> transportsMap
    ) {
        //Only used to build actual transports (needs ORIGIN and DESTINATION same)
        Transport pohFairyTransport = new Transport(pohFairyRing, pohFairyRing, "DIQ", FAIRY_RING, true, 5);
        return createTransportsToPoh(pohFairyTransport, transportsMap);
    }

    /**
     * Connecting the PoH spirit tree to all other spirit tree and vise versa
     *
     * @param pohSpiritTree position of the PoH spirit tree (exitPortal until mapping inside Poh)
     * @param transportsMap map from which currently present spirit tree transports are found
     * @return new map with PoH fairy spirit tree transports added
     */
    public static Map<WorldPoint, Set<Transport>> createSpiritTreeMap(
            WorldPoint pohSpiritTree,
            Map<WorldPoint, Set<Transport>> transportsMap
    ) {
        //Only used to build actual transports (needs ORIGIN and DESTINATION same)
        Transport pohSpiritTransport = new Transport(pohSpiritTree, pohSpiritTree, "C: Your house", SPIRIT_TREE, true, 5);
        return createTransportsToPoh(pohSpiritTransport, transportsMap);
    }

    /**
     * Uses a template (PoH) transport to connect all transports to
     * other transports of the same type, both by adding routes from the PoH transport to
     * the existing transports and vice versa.
     *
     * @param pohTempTransport the transport object representing the PoH transport to be connected.
     *                         The TransportType is used to filter for existing transports
     *                         The origin and destination are used to build the connecting transport
     * @param transportsMap    a map of existing transports, where each key represents a WorldPoint
     *                         and the value is a set of transports originating or terminating at
     *                         that point
     * @return a new map containing the updated set of transports where connections have been
     * added between the provided PoH transport and existing transports of the same type
     */
    public static Map<WorldPoint, Set<Transport>> createTransportsToPoh(Transport pohTempTransport, Map<WorldPoint, Set<Transport>> transportsMap) {
        WorldPoint pohExitPortal = pohTempTransport.getOrigin();
        TransportType type = pohTempTransport.getType();
        Map<WorldPoint, Set<Transport>> newTransportsMap = new HashMap<>();
        transportsMap.entrySet().stream()
                .filter(e -> e.getValue().stream().anyMatch(t -> t.getType() == type)).findFirst().ifPresent(e -> {
                WorldPoint existingRingPoint = e.getKey();
                for (Transport existingRingTransport : new HashSet<>(e.getValue())) {
                if (existingRingTransport.getType() != type) continue;
                // add from poh
                newTransportsMap
                .computeIfAbsent(pohExitPortal, k -> new HashSet<>())
                .add(new Transport(pohTempTransport, existingRingTransport));

                // add to poh
                newTransportsMap
                .computeIfAbsent(existingRingPoint, k -> new HashSet<>())
                .add(new Transport(existingRingTransport, pohTempTransport));
                }
                });

        return newTransportsMap;
    }

}

