// ----- TransportType (net.runelite.client.plugins.microbot.shortestpath) -----
public enum TransportType {
    TRANSPORT,
    AGILITY_SHORTCUT,
    GRAPPLE_SHORTCUT,
    BOAT,
    CANOE,
    CHARTER_SHIP,
    SHIP,
    FAIRY_RING,
    QUETZAL,
    GNOME_GLIDER,
    MINECART,
    POH,
    SPIRIT_TREE,
    TELEPORTATION_LEVER,
    TELEPORTATION_PORTAL,
    TELEPORTATION_MINIGAME,
    TELEPORTATION_ITEM,
    TELEPORTATION_SPELL,
    WILDERNESS_OBELISK,
    MAGIC_CARPET,
    NPC;

    /*
     * Indicates whether a TransportType is a teleport.
     * Levers, portals and wilderness obelisks are considered transports
     * and not teleports because they have a pre-defined origin and no
     * wilderness level limit.
     */
    public static boolean isTeleport(TransportType transportType) {
        if (transportType == null) {
            return false;
        }
        switch (transportType) {
            case TELEPORTATION_ITEM:
            case TELEPORTATION_MINIGAME:
            case TELEPORTATION_SPELL:
                return true;
            default:
                return false;
        }
    }

}

// ----- TransportVarPlayer (net.runelite.client.plugins.microbot.shortestpath) -----
@Getter
public class TransportVarPlayer {

    private final int varplayerId;
    private final int value;
    private final Operator operator;

    public TransportVarPlayer(int varplayerId, int value, Operator operator) {
        this.varplayerId = varplayerId;
        this.value = value;
        this.operator = operator;
    }

    public boolean matches(int actualValue) {
        switch (operator) {
            case EQUAL:
                return actualValue == value;
            case GREATER_THAN:
                return actualValue > value;
            case LESS_THAN:
                return actualValue < value;
            case BIT_SET:
                return (actualValue & value) > 0;
            case COOLDOWN_MINUTES:
                return ((System.currentTimeMillis() / 60000) - actualValue) > value;
            default:
                throw new IllegalArgumentException("Unsupported operator: " + operator);
        }
    }

    public enum Operator {
        BIT_SET,
        COOLDOWN_MINUTES,
        EQUAL,
        GREATER_THAN,
        LESS_THAN
    }

    @Override
    public String toString()
    {
        return "TransportVarPlayer{" +
                "varplayerId=" + varplayerId +
                ", value=" + value +
                ", operator=" + operator +
                '}';
    }
}

