// ----- CheckboxPanel (net.runelite.client.plugins.microbot.shortestpath.components) -----
public class CheckboxPanel extends JPanel {

    String MOUNTED_GLORY = "mountedGlory";
    String MOUNTED_DIGSITE = "mountedDigsite";
    String MOUNTED_XERICS = "mountedXerics";
    String MOUNTED_MYTHS = "mountedMyths";
    String FAIRY_RING = "fairyRing";
    String WILDY_OBELISK = "wildyObelisk";
    String SPIRIT_TREE = "spiritTree";

    private final JCheckBox mountedGloryCb;
    private final JCheckBox mountedDigsiteCb;
    private final JCheckBox mountedXericsCb;
    private final JCheckBox mountedMythCapeCb;
    public final JCheckBox fairyRingCb;
    public final JCheckBox spiritTreeCb;
    private final JCheckBox wildernessObeliskCb;

    public CheckboxPanel() {
        setBorder(new TitledBorder("House Features"));
        GridBagLayout layout = new GridBagLayout();
        setLayout(layout);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.anchor = GridBagConstraints.NORTHWEST;
        gbc.insets.set(2, 4, 2, 4);

        mountedGloryCb = new JCheckBox("Mounted Amulet of Glory");
        mountedGloryCb.setEnabled(false);
        add(mountedGloryCb, gbc);

        gbc.gridy++;
        mountedDigsiteCb = new JCheckBox("Mounted Digsite Pendant");
        mountedDigsiteCb.setEnabled(false);
        add(mountedDigsiteCb, gbc);

        gbc.gridy++;
        mountedXericsCb = new JCheckBox("Mounted Xeric's Talisman");
        mountedXericsCb.setEnabled(false);
        add(mountedXericsCb, gbc);

        gbc.gridy++;
        mountedMythCapeCb = new JCheckBox("Mounted Mythical Cape");
        mountedMythCapeCb.setEnabled(false);
        add(mountedMythCapeCb, gbc);

        gbc.gridy++;
        fairyRingCb = new JCheckBox("Fairy ring");
        fairyRingCb.setEnabled(false);
        add(fairyRingCb, gbc);

        gbc.gridy++;
        spiritTreeCb = new JCheckBox("Spirit tree");
        spiritTreeCb.setEnabled(false);
        add(spiritTreeCb, gbc);

        gbc.gridy++;
        wildernessObeliskCb = new JCheckBox("Wilderness obelisk");
        wildernessObeliskCb.setEnabled(false);
        wildernessObeliskCb.setVisible(false);
        add(wildernessObeliskCb, gbc);

        hookListeners();
        loadConfigs();
    }

    private void hookListeners() {
        mountedGloryCb.addActionListener(e -> setBool(MOUNTED_GLORY, mountedGloryCb.isSelected()));
        mountedDigsiteCb.addActionListener(e -> setBool(MOUNTED_DIGSITE, mountedDigsiteCb.isSelected()));
        mountedXericsCb.addActionListener(e -> setBool(MOUNTED_XERICS, mountedXericsCb.isSelected()));
        mountedMythCapeCb.addActionListener(e -> setBool(MOUNTED_MYTHS, mountedMythCapeCb.isSelected()));
        fairyRingCb.addActionListener(e -> setBool(FAIRY_RING, fairyRingCb.isSelected()));
        spiritTreeCb.addActionListener(e -> setBool(SPIRIT_TREE, spiritTreeCb.isSelected()));
        wildernessObeliskCb.addActionListener(e -> setBool(WILDY_OBELISK, wildernessObeliskCb.isSelected()));
    }

    private void setBool(String key, boolean value) {
        Microbot.getConfigManager().setConfiguration(CONFIG_GROUP, key, value);
    }

    private boolean getBool(String key) {
        try {
            return Microbot.getConfigManager().getConfiguration(CONFIG_GROUP, key, Boolean.class);
        } catch (NullPointerException e) {
            Microbot.log("Failed to poh checkbox config for " + key);
            return false;
        }
    }

    private void saveConfigs() {
        setBool(MOUNTED_GLORY, mountedGloryCb.isSelected());
        setBool(MOUNTED_DIGSITE, mountedDigsiteCb.isSelected());
        setBool(MOUNTED_XERICS, mountedXericsCb.isSelected());
        setBool(MOUNTED_MYTHS, mountedMythCapeCb.isSelected());
        setBool(FAIRY_RING, fairyRingCb.isSelected());
        setBool(SPIRIT_TREE, spiritTreeCb.isSelected());
        setBool(WILDY_OBELISK, wildernessObeliskCb.isSelected());
    }

    private void loadConfigs() {
        mountedGloryCb.setSelected(getBool(MOUNTED_GLORY));
        mountedDigsiteCb.setSelected(getBool(MOUNTED_DIGSITE));
        mountedXericsCb.setSelected(getBool(MOUNTED_XERICS));
        mountedMythCapeCb.setSelected(getBool(MOUNTED_MYTHS));
        fairyRingCb.setSelected(getBool(FAIRY_RING));
        spiritTreeCb.setSelected(getBool(SPIRIT_TREE));
        wildernessObeliskCb.setSelected(getBool(WILDY_OBELISK));
    }

    public void detectPohFacilities() {
        mountedGloryCb.setSelected(MountedGlory.getObject() != null);
        mountedDigsiteCb.setSelected(MountedDigsite.getObject() != null);
        mountedXericsCb.setSelected(MountedXerics.getObject() != null);
        mountedMythCapeCb.setSelected(MountedMythical.getObject() != null);
        fairyRingCb.setSelected(PohTeleports.getFairyRings() != null);
        spiritTreeCb.setSelected(PohTeleports.getSpiritTree() != null);
        saveConfigs();
    }

    public Set<PohTeleport> getTeleports() {
        Set<PohTeleport> teleports = new HashSet<>();
        if (mountedDigsiteCb.isSelected()) {
            teleports.addAll(Arrays.asList(MountedDigsite.values()));
        }
        if (mountedXericsCb.isSelected()) {
            teleports.addAll(Arrays.asList(MountedXerics.values()));
        }
        if (mountedGloryCb.isSelected()) {
            teleports.addAll(Arrays.asList(MountedGlory.values()));
        }
        if (mountedMythCapeCb.isSelected()) {
            teleports.addAll(Arrays.asList(MountedMythical.values()));
        }
        return teleports;
    }
}

// ----- ComboBoxIconEntry (net.runelite.client.plugins.microbot.shortestpath.components) -----
@AllArgsConstructor
@Getter
public class ComboBoxIconEntry
{
    private Icon icon;
    private String text;
    @Nullable
    private Object data;
}

// ----- ComboBoxListRenderer (net.runelite.client.plugins.microbot.shortestpath.components) -----
public final class ComboBoxListRenderer extends JLabel implements ListCellRenderer
{
    @Setter
    private String defaultText = "Select an option...";

    @Override
    public Component getListCellRendererComponent(JList list, Object o, int index, boolean isSelected, boolean cellHasFocus)
    {
        if (isSelected)
        {
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            setForeground(Color.WHITE);
        }
        else
        {
            setBackground(list.getBackground());
            setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        }

        setBorder(new EmptyBorder(5, 10, 5, 10));
        setIcon(null);

        String text;
        // If using setSelectedItem(null) or setSelectedIndex(-1) show default text until a selection is made
        if (index == -1 && o == null)
        {
            text = defaultText;
        }
        else if (o instanceof Enum)
        {
            text = Text.titleCase((Enum) o);
        }
        else if (o instanceof ComboBoxIconEntry)
        {
            ComboBoxIconEntry e = (ComboBoxIconEntry) o;
            text = e.getText();
            setIcon(e.getIcon());
        }
        else
        {
            text = o.toString();
        }

        setText(text);

        return this;
    }
}

// ----- EnumListPanel (net.runelite.client.plugins.microbot.shortestpath.components) -----
public class EnumListPanel<T extends Enum<T> & PohTeleport> extends JPanel {

    private final DefaultListModel<T> selectedModel = new DefaultListModel<>();
    private JList<T> teleportList;

    private final String title;
    private final Class<T> enumClass;

    public EnumListPanel(Class<T> enumClass, String title) {
        this.title = title;
        this.enumClass = enumClass;
        setBorder(new TitledBorder(title));
        setLayout(new GridBagLayout());

        teleportList = new JList<>(selectedModel);
        teleportList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        teleportList.setVisibleRowCount(6);
        teleportList.setCellRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                setText(value.toString());
                return this;
            }
        });

        JScrollPane scroll = new JScrollPane(teleportList);
        // Ensure the panel doesn't render too small
        Dimension minSize = new Dimension(180, 150);
        scroll.setMinimumSize(minSize);
        scroll.setPreferredSize(minSize);

        GridBagConstraints scrollGbc = new GridBagConstraints();
        scrollGbc.gridx = 0;
        scrollGbc.gridy = 0;
        scrollGbc.gridwidth = 1;
        scrollGbc.gridheight = 1;
        scrollGbc.weightx = 0.0; // Don't expand horizontally
        scrollGbc.weighty = 1.0; // Allow vertical expansion
        scrollGbc.fill = GridBagConstraints.BOTH; // Fill available space in both directions
        scrollGbc.anchor = GridBagConstraints.NORTHWEST; // Anchor to northwest
        scrollGbc.insets = new Insets(0, 0, 8, 0); // Add spacing below the scroll pane
        add(scroll, scrollGbc);

        // Load initial state
        loadTeleportsFromConfig().forEach(selectedModel::addElement);
    }

    public void setAll(java.util.List<T> teleports) {
        selectedModel.clear();
        teleports.forEach(selectedModel::addElement);
        saveTeleportsToConfig();
    }

    public void saveTeleportsToConfig() {
        java.util.List<T> teleports = new ArrayList<>();
        for (int i = 0; i < selectedModel.getSize(); i++) {
            teleports.add(selectedModel.get(i));
        }
        String serialized = teleports.stream()
                .map(Enum::name)
                .collect(Collectors.joining(","));
        Microbot.getConfigManager().setConfiguration(CONFIG_GROUP, title, serialized);
    }

    public java.util.List<T> loadTeleportsFromConfig() {
        String raw = Microbot.getConfigManager().getConfiguration(CONFIG_GROUP, title);
        if (raw == null || raw.trim().isEmpty()) {
            return List.of();
        }
        return Arrays.stream(raw.split(","))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .map(name ->
                {
                try {
                return Enum.valueOf(enumClass, name);
                } catch (IllegalArgumentException ex) {
                return null;
                }
                })
                .filter(Objects::nonNull)
                .collect(Collectors.toList());
    }

    public Set<PohTeleport> getTeleports() {
        Set<PohTeleport> teleports = new HashSet<>();
        for (int i = 0; i < selectedModel.getSize(); i++) {
            teleports.add((PohTeleport) selectedModel.get(i));
        }
        return teleports;
    }
}

// ----- ExitTilePanel (net.runelite.client.plugins.microbot.shortestpath.components) -----
public class ExitTilePanel extends JPanel {

    String POH_TILE_KEY = "pohExitPortalTile";
    private JTextField tileField;

    public ExitTilePanel() {
        setBorder(new TitledBorder("Exit Portal Location"));
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.insets.set(2, 4, 2, 4);
        gbc.anchor = GridBagConstraints.WEST;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.weightx = 1.0;

        tileField = new JTextField();
        tileField.setBorder(null);
        tileField.setOpaque(false);
        tileField.setSelectedTextColor(Color.WHITE);
        tileField.setSelectionColor(ColorScheme.BRAND_ORANGE_TRANSPARENT);
        tileField.setPreferredSize(new Dimension(150, 20));
        tileField.setEnabled(false);
        add(tileField, gbc);
        loadTile();
    }

    private void loadTile() {
        try {
            String tile = Microbot.getConfigManager().getConfiguration(ShortestPathPlugin.CONFIG_GROUP, POH_TILE_KEY);
            tileField.setText(tile);
        } catch (NullPointerException e) {
            Microbot.log("Failed to load poh tile config");
            tileField.setText("");
        }
    }

    private void saveTile() {
        Microbot.getConfigManager().setConfiguration(ShortestPathPlugin.CONFIG_GROUP, POH_TILE_KEY, tileField.getText());
    }

    public void detectTile() {
        GameObject exitPortal = Rs2GameObject.getGameObject(POH_EXIT_PORTAL);
        if (exitPortal == null) {
            Microbot.log("Failed to find exit portal");
        } else {
            WorldPoint wp = WorldPoint.fromLocalInstance(Microbot.getClient(), exitPortal.getLocalLocation());
            String tileString = String.format("%s, %s, %s", wp.getX(), wp.getY(), wp.getPlane());
            tileField.setText(tileString);
            saveTile();
        }
    }

    public WorldPoint getTile() {
        String tileString = tileField.getText();
        if (tileString.isEmpty()) {
            return null;
        }
        String[] tileParts = tileString.split(",");
        if (tileParts.length != 3) {
            return null;
        }
        return new WorldPoint(Integer.parseInt(tileParts[0].trim()), Integer.parseInt(tileParts[1].trim()), Integer.parseInt(tileParts[2].trim()));
    }
}

// ----- JewelleryBoxPanel (net.runelite.client.plugins.microbot.shortestpath.components) -----
public class JewelleryBoxPanel extends JPanel {
    String JEWELLERY_BOX = "jewelleryBox";

    private JComboBox<JewelleryBoxType> jewelleryBoxCmb;

    public JewelleryBoxPanel() {
        setBorder(new TitledBorder("Jewellery Box"));
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.insets.set(2, 4, 2, 4);
        gbc.anchor = GridBagConstraints.WEST;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.weightx = 1.0;
        // Jewellery box dropdown
        add(new JLabel("Type"), gbc);
        jewelleryBoxCmb = new JComboBox<>(JewelleryBoxType.values());
        gbc.gridx++;
        add(jewelleryBoxCmb, gbc);

        jewelleryBoxCmb.addActionListener(e -> saveJewelleryBoxToConfig());
        jewelleryBoxCmb.setEnabled(false);
        loadJewelleryBox();
    }

    public void detectJewelleryBox() {
        jewelleryBoxCmb.setSelectedItem(JewelleryBoxType.getCurrentJewelleryBoxType());
        saveJewelleryBoxToConfig();
    }

    public void loadJewelleryBox() {
        try {
            JewelleryBoxType loadedBox = Microbot.getConfigManager().getConfiguration(CONFIG_GROUP, JEWELLERY_BOX, JewelleryBoxType.class);
            jewelleryBoxCmb.setSelectedItem(loadedBox);
        } catch (NullPointerException e) {
            Microbot.log("Failed to load jewellery box config");
            jewelleryBoxCmb.setSelectedItem(JewelleryBoxType.NONE);
        }
    }

    private void saveJewelleryBoxToConfig() {
        JewelleryBoxType config = (JewelleryBoxType) jewelleryBoxCmb.getSelectedItem();
        if (config == null) {
            config = JewelleryBoxType.NONE;
        }
        Microbot.getConfigManager().setConfiguration(CONFIG_GROUP, JEWELLERY_BOX, config);
    }

    public Set<PohTeleport> getTeleports() {
        JewelleryBoxType jewelleryBoxType = (JewelleryBoxType) jewelleryBoxCmb.getSelectedItem();
        return jewelleryBoxType == null ? Set.of() : new HashSet<>(jewelleryBoxType.getAvailableTeleports());
    }
}


