@Value
@RequiredArgsConstructor
public class MicrobotPluginConfigurationDescriptor
{
    private final String name;
    private final String description;
    private final String[] tags;

    // Can be null if its not an actual plugin (RuneLite / ChatColors)
    @Nullable
    private final Plugin plugin;

    // Can be null if it has no more configuration than the on/off toggle
    @Nullable
    private final Config config;

    @Nullable
    private final ConfigDescriptor configDescriptor;

    @Nullable
    private final List<String> conflicts;

    public MicrobotPluginConfigurationDescriptor(String name, String description, String[] tags, Config config, ConfigDescriptor configDescriptor)
    {
        this(name, description, tags, null, config, configDescriptor, null);
    }

    /**
     * Creates a menu item for linking to a support page for the plugin
     *
     * @return A {@link JMenuItem} which opens the plugin's wiki page URL in the browser when clicked
     */
    @Nullable
    JMenuItem createSupportMenuItem(Plugin plugin)
    {
        String iname = getInternalPluginHubName();
        if (iname != null)
        {
            JMenuItem menuItem = new JMenuItem("Wiki");
            menuItem.addActionListener(e -> LinkBrowser.browse("https://chsami.github.io/Microbot-Hub/" + iname));
            return menuItem;
        }

        JMenuItem menuItem = new JMenuItem("Wiki");
        menuItem.addActionListener(e -> LinkBrowser.browse("https://chsami.github.io/Microbot-Hub/" + (plugin != null ? plugin.getClass().getSimpleName() : "")));
        return menuItem;
    }

    @Nullable
    String getInternalPluginHubName()
    {
        if (plugin == null)
        {
            return null;
        }

        return ExternalPluginManager.getInternalName(plugin.getClass());
    }
}

