// ----- WeaponsGenerator (net.runelite.client.plugins.microbot.util.combat.weapons) -----
@Slf4j
@Getter
public class WeaponsGenerator
{
    private static final WeaponIds weaponIds = new WeaponIds();

    public static Map<Integer, Weapon> generate()
    {
        final Map<Integer, Weapon> standardWeapons = generateStandard(weaponIds.getStandardWeapons());
        final Map<Integer, Weapon> nonStandardWeapons = generateNonstandard(weaponIds.getNonStandardWeapons());
        final Map<Integer, Weapon> weapons = new HashMap<>();
        weapons.putAll(standardWeapons);
        weapons.putAll(nonStandardWeapons);
        return weapons;
    }

    private static Map<Integer, Weapon> generateStandard(
        Set<Pair<Set<Integer>, Function<Integer, Weapon>>> standardWeapons)
    {
        final Map<Integer, Weapon> weapons = new HashMap<>();
        for (Pair<Set<Integer>, Function<Integer, Weapon>> idsConstructorPair : standardWeapons)
        {
            for (Integer weaponId : idsConstructorPair.getLeft())
            {
                Weapon weapon = idsConstructorPair.getRight().apply(weaponId);
                if (weapon != null)
                {
                if (weapons.containsKey(weapon.id))
                {
                log.debug("Duplicate weapon entry.");
                log.debug("Trying to insert {}, Existing {}", weapon, weapons.get(weapon.id));
                }
                weapons.put(weapon.id, weapon);
                }
            }
        }
        return weapons;
    }

    private static Map<Integer, Weapon> generateNonstandard(
        Set<Pair<Set<List<Integer>>, Function<List<Integer>, Weapon>>> nonStandardWeapons)
    {
        final Map<Integer, Weapon> weapons = new HashMap<>();
        for (Pair<Set<List<Integer>>, Function<List<Integer>, Weapon>> idsConstructorPair : nonStandardWeapons)
        {
            for (List<Integer> weaponData : idsConstructorPair.getLeft())
            {
                Weapon weapon = idsConstructorPair.getRight().apply(weaponData);
                if (weapon != null)
                {
                weapons.put(weapon.id, weapon);
                }
            }
        }
        return weapons;
    }
}


// ========== Package: net.runelite.client.plugins.microbot.util.coords ==========

// ----- Rs2LocalPoint (net.runelite.client.plugins.microbot.util.coords) -----
public class Rs2LocalPoint {
    /**
     * Used to convert a worldpoint in an instance to a localpoint
     * @param worldPoint
     * @return
     */
    public static LocalPoint fromWorldInstance(WorldPoint worldPoint)
    {
        int[][][] instanceTemplateChunks = Microbot.getClient().getTopLevelWorldView().getInstanceTemplateChunks();
        // Extract the coordinates from the WorldPoint
        int worldX = worldPoint.getX();
        int worldY = worldPoint.getY();
        int worldPlane = Microbot.getClient().getTopLevelWorldView().getPlane();

        // Loop through all chunks to find which one contains the world point
        for (int chunkX = 0; chunkX < instanceTemplateChunks[worldPlane].length; chunkX++)
        {
            for (int chunkY = 0; chunkY < instanceTemplateChunks[worldPlane][chunkX].length; chunkY++)
            {
                // Get the template chunk at this chunk position
                int templateChunk = instanceTemplateChunks[worldPlane][chunkX][chunkY];

                // Extract rotation, template chunk coordinates, and plane
                int rotation = (templateChunk >> 1) & 0x3;
                int templateChunkY = (templateChunk >> 3 & 0x7FF) * CHUNK_SIZE;
                int templateChunkX = (templateChunk >> 14 & 0x3FF) * CHUNK_SIZE;
                int templateChunkPlane = (templateChunk >> 24) & 0x3;

                // Check if the WorldPoint matches this chunk (after reversing rotation)
                WorldPoint rotatedWorldPoint = rotate(new WorldPoint(worldX, worldY, templateChunkPlane), rotation);

                if (rotatedWorldPoint.getX() >= templateChunkX && rotatedWorldPoint.getX() < templateChunkX + CHUNK_SIZE
                && rotatedWorldPoint.getY() >= templateChunkY && rotatedWorldPoint.getY() < templateChunkY + CHUNK_SIZE)
                {
                // Calculate local coordinates within the scene
                int localX = (rotatedWorldPoint.getX() - templateChunkX) + (chunkX * CHUNK_SIZE);
                int localY = (rotatedWorldPoint.getY() - templateChunkY) + (chunkY * CHUNK_SIZE);

                // Return the corresponding LocalPoint
                return  LocalPoint.fromScene(localX, localY, Microbot.getClient().getTopLevelWorldView());
                }
            }
        }

        // Return null if no matching chunk is found
        return null;
    }

    /**
     * Rotate the coordinates in the chunk according to chunk rotation
     *
     * @param point point
     * @param rotation rotation
     * @return world point
     */
    public static WorldPoint rotate(WorldPoint point, int rotation)
    {
        int chunkX = point.getX() & ~(CHUNK_SIZE - 1);
        int chunkY = point.getY() & ~(CHUNK_SIZE - 1);
        int x = point.getX() & (CHUNK_SIZE - 1);
        int y = point.getY() & (CHUNK_SIZE - 1);
        switch (rotation)
        {
            case 1:
                return new WorldPoint(chunkX + y, chunkY + (CHUNK_SIZE - 1 - x), point.getPlane());
            case 2:
                return new WorldPoint(chunkX + (CHUNK_SIZE - 1 - x), chunkY + (CHUNK_SIZE - 1 - y), point.getPlane());
            case 3:
                return new WorldPoint(chunkX + (CHUNK_SIZE - 1 - y), chunkY + x, point.getPlane());
        }
        return point;
    }

    public static Integer worldToLocalDistance(int distance) {
        return distance * Perspective.LOCAL_TILE_SIZE;
    }

    public static Integer localToWorldDistance(int distance) {
        return distance / Perspective.LOCAL_TILE_SIZE;
    }
}

// ----- Rs2WorldArea (net.runelite.client.plugins.microbot.util.coords) -----
public class Rs2WorldArea extends WorldArea {
    public Rs2WorldArea(int x, int y, int width, int height, int plane) {
        super(x, y, width, height, plane);
    }

    public Rs2WorldArea(WorldPoint location, int width, int height) {
        super(location, width, height);
    }

    public Rs2WorldArea(WorldArea area) {
        super(area.getX(), area.getY(), area.getWidth(), area.getHeight(), area.getPlane());
    }

    public Rs2WorldArea(WorldPoint swLocation, WorldPoint neLocation)
    {
        super(swLocation, neLocation.getX() - swLocation.getX() + 1, neLocation.getY() - swLocation.getY() + 1);
    }

    public Rs2WorldArea offset(int size) {
        return new Rs2WorldArea(getX() - size, getY() - size, getWidth() + (size * 2), getHeight() + (size * 2), getPlane());
    }

    /**
     * Checks whether this area is within melee distance of another without blocking in-between.
     *
     * @param wv the worldview to test in
     * @param other the other area
     * @return true if in melee distance without blocking, false otherwise
     */
    public boolean canMelee(WorldView wv, Rs2WorldArea other) {
        if (!isInMeleeDistance(other)) {
            return false;
        }
        Point p1 = this.getComparisonPoint(other);
        Point p2 = other.getComparisonPoint(this);
        int dx = p2.getX() - p1.getX();
        int dy = p2.getY() - p1.getY();
        return this.canTravelInDirection(wv, dx, dy);
    }

    /**
     * Gets the point within this area that is closest to another.
     *
     * @param other the other area
     * @return the closest point to the passed area
     */
    private Point getComparisonPoint(WorldArea other) {
        int x = Math.min(Math.max(other.getX(),this.getX()), this.getX() + this.getWidth() - 1);
        int y = Math.min(Math.max(other.getY(),this.getY()), this.getY() + this.getHeight() - 1);
        return new Point(x, y);
    }

    public List<WorldPoint> getInteractable()
    {

        List<WorldPoint> surrounding = this.offset(1).toWorldPointList();

        surrounding.removeIf(this::contains);

        return surrounding.stream()
                .filter(Rs2Tile::isWalkable)
                .collect(Collectors.toList());
    }
}

// ----- Rs2WorldPoint (net.runelite.client.plugins.microbot.util.coords) -----
@Slf4j
public class Rs2WorldPoint {
    @Setter
    private WorldPoint worldPoint;

    // Constructor accepting coordinates
    public Rs2WorldPoint(int x, int y, int plane) {
        this.worldPoint = new WorldPoint(x, y, plane);
    }

    // Constructor accepting a WorldPoint instance
    public Rs2WorldPoint(WorldPoint worldPoint) {
        this.worldPoint = worldPoint;

    }

    // Getter methods
    public int getX() {
        return worldPoint.getX();
    }

    public int getY() {
        return worldPoint.getY();
    }

    public int getPlane() {
        return worldPoint.getPlane();
    }

    public WorldPoint getWorldPoint() {
        return worldPoint;
    }

    public List<WorldPoint> pathTo(WorldPoint other)
    {
        return pathTo(other, false);
    }

    public List<WorldPoint> pathTo(WorldPoint other, boolean fullPath)
    {
        Client client = Microbot.getClient();
        if (getPlane() != other.getPlane())
        {
            return null;
        }

        LocalPoint sourceLp = LocalPoint.fromWorld(client.getTopLevelWorldView(), getX(), getY());
        LocalPoint targetLp = LocalPoint.fromWorld(client.getTopLevelWorldView(), other.getX(), other.getY());
        if (sourceLp == null || targetLp == null)
        {
            return null;
        }

        int thisX = sourceLp.getSceneX();
        int thisY = sourceLp.getSceneY();
        int otherX = targetLp.getSceneX();
        int otherY = targetLp.getSceneY();

        Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
        Tile sourceTile = tiles[getPlane()][thisX][thisY];

        Tile targetTile = tiles[getPlane()][otherX][otherY];
        List<Tile> checkpointTiles = fullPath ? Rs2Tile.fullPathTo(sourceTile,targetTile) : Rs2Tile.pathTo(sourceTile, targetTile);
        if (checkpointTiles == null)
        {
            return null;
        }
        List<WorldPoint> checkpointWPs = new ArrayList<>();
        for (Tile checkpointTile : checkpointTiles)
        {
            if (checkpointTile == null)
            {
                break;
            }
            checkpointWPs.add(checkpointTile.getWorldLocation());
        }
        return checkpointWPs;
    }

    public int distanceToPath(WorldPoint other)
    {
        if(other == null)
        {
            return Integer.MAX_VALUE;
        }
        List<WorldPoint> checkpointWPs = this.pathTo(other);
        if (checkpointWPs == null)
        {
            // No path found
            return Integer.MAX_VALUE;
        }

        WorldPoint destinationPoint = checkpointWPs.get(checkpointWPs.size() - 1);
        if (other.getX() != destinationPoint.getX() || other.getY() != destinationPoint.getY())
        {
            // Path found but not to the requested tile
            return Integer.MAX_VALUE;
        }
        WorldPoint Point1 = getWorldPoint();
        int distance = 0;
        for (WorldPoint Point2 : checkpointWPs)
        {
            distance += Point1.distanceTo2D(Point2);
            Point1 = Point2;
        }
        return distance;
    }

    /**
     * Converts an instanced worldPoint coordinate to a global worldpoint
     * this can be used for getting objects in instanced room by location
     * @param worldPoint
     * @return
     */
    public static WorldPoint convertInstancedWorldPoint(WorldPoint worldPoint) {
        if (worldPoint == null) return null;

        LocalPoint l = Rs2LocalPoint.fromWorldInstance(worldPoint);
        // If we're in PoH this function still gets called by handleDoors for the destination tile of the teleport.
        // Since that tile is not in the instance map, it returns null.
        // We can just return the worldPoint as is OR we can return null.
        if (l == null) return null;
        WorldPoint globalWorldPoint = WorldPoint.fromLocal(Microbot.getClient(), l);

        return globalWorldPoint;
    }

    public static WorldPoint toLocalInstance(WorldPoint worldPoint) {
        if (worldPoint == null) return null;

        return WorldPoint.toLocalInstance(Microbot.getClient().getTopLevelWorldView(),worldPoint).stream().findFirst().orElse(null);
    }

    /**
     * Calculate the distance quikcly with Chebyshev distance
     * https://iq.opengenus.org/euclidean-vs-manhattan-vs-chebyshev-distance/
     * @param a
     * @param b
     * @return
     */
    public static int quickDistance(WorldPoint a, WorldPoint b) {
        int dx = Math.abs(a.getX() - b.getX());
        int dy = Math.abs(normalizeY(a) - normalizeY(b));
        return Math.max(dx, dy);
    }

    /**
     * Normalize a point to use for comparison
     * This is used for caves
     * @param point
     * @return
     */
    public static int normalizeY(WorldPoint point) {
        int y = point.getY();

        if (y > 6400) {
            return y - 6400;
        }
        return y;
    }

    // Override equals, hashCode, and toString if necessary
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj instanceof Rs2WorldPoint) {
            Rs2WorldPoint other = (Rs2WorldPoint) obj;
            return worldPoint.equals(other.worldPoint);
        }
        return false;
    }

    @Override
    public int hashCode() {
        return worldPoint.hashCode();
    }

    @Override
    public String toString() {
        return worldPoint.toString();
    }
}


