// ----- JewelleryBoxType (net.runelite.client.plugins.microbot.util.poh.data) -----
@Getter
@RequiredArgsConstructor
public enum JewelleryBoxType {
    NONE(-1),
    BASIC(ObjectID.POH_JEWELLERY_BOX_1),
    FANCY(ObjectID.POH_JEWELLERY_BOX_2),
    ORNATE(ObjectID.POH_JEWELLERY_BOX_3);

    private final int objectId;

    /**
     * Gets all teleports available for this jewellery box type
     */
    public List<JewelleryBox> getAvailableTeleports() {
        if (this == NONE) {
            return List.of();
        }
        return JewelleryBox.getAvailableTeleports(this);
    }

    /**
     * Gets all jewellery box object IDs (excluding NONE)
     */
    public static Integer[] getJewelleryBoxIds() {
        return Arrays.stream(values())
                .filter(box -> box != NONE)
                .map(JewelleryBoxType::getObjectId)
                .toArray(Integer[]::new);
    }

    /**
     * Gets the jewellery box GameObject if present in POH
     */
    public static GameObject getObject() {
        return Rs2GameObject.getGameObject(getJewelleryBoxIds());
    }

    /**
     * Determines the current jewellery box type in the POH
     */
    public static JewelleryBoxType getCurrentJewelleryBoxType() {
        GameObject go = getObject();
        if (go == null) {
            return NONE;
        }

        for (JewelleryBoxType boxType : values()) {
            if (boxType.objectId == go.getId()) {
                return boxType;
            }
        }
        return NONE;
    }

    /**
     * Gets the jewellery box type for the specified GameObject
     * @param go GameObject to check. If null, returns null.
     * @return JewelleryBoxType or null if not found.
     */
    public static JewelleryBoxType getJewelleryBoxType(GameObject go) {
        if (go == null) {
            return null;
        }
        int objId = go.getId();
        for (JewelleryBoxType jewelleryBoxType : JewelleryBoxType.values()) {
            if (jewelleryBoxType.objectId == objId) {
                return jewelleryBoxType;
            }
        }
        return null;
    }

}

// ----- MountedDigsite (net.runelite.client.plugins.microbot.util.poh.data) -----
@Getter
@RequiredArgsConstructor
public enum MountedDigsite implements PohTeleport {
    FOSSIL_ISLAND(ObjectID.POH_AMULET_DIG_FOSSIL, "Fossil Island", TeleportLocationData.HOUSE_ON_THE_HILL.getLocation()),
    DIGSITE(ObjectID.POH_AMULET_DIG_DIGSITE, "Digsite", TeleportLocationData.DIGSITE.getLocation()),
    LITHKREN(ObjectID.POH_AMULET_DIG_LITHKREN, "Lithkren", TeleportLocationData.LITHKREN.getLocation()),
    ;

    private final int objectId;
    private final String destinationName;
    private final WorldPoint destination;

    private final int duration = 4;

    @Override
    public boolean execute() {
        DecorativeObject pendant = getObject();
        if (pendant == null) {
            return false;
        }
        if (pendant.getId() == objectId) {
            //The correct id for the object means it has the right left click option, so we can just use that.
            return Rs2GameObject.interact(pendant, destinationName);
        }
        Widget widget = getWidget();
        if (widget == null) {
            if (Rs2GameObject.interact(pendant, "Teleport menu")) {
                if (!sleepUntil(() -> getWidget() != null, 10000)) {
                return false;
                }
            }
        }
        return Rs2Widget.clickWidget(destinationName);
    }

    public static final Integer[] IDS = {ObjectID.POH_AMULET_DIGSITE, ObjectID.POH_AMULET_DIG_LITHKREN, ObjectID.POH_AMULET_DIG_FOSSIL, ObjectID.POH_AMULET_DIG_DIGSITE};

    public static DecorativeObject getObject() {
        return Rs2GameObject.getDecorativeObject(IDS);
    }

    public static boolean isMountedDigsite(DecorativeObject go) {
        if (go == null) return false;
        for (int objId : IDS) {
            if (objId == go.getId()) return true;
        }
        return false;
    }

    private static Widget getWidget() {
        return Rs2Widget.getWidget(InterfaceID.MENU, 3);
    }

    @Override
    public String displayInfo() {
        return "MountedDigsite -> " + destinationName;
    }

}

