// ----- AutoWoodcutterConfig (net.runelite.client.plugins.microbot.woodcutter) -----
@ConfigGroup("autowoodcutter")
public interface AutoWoodcutterConfig extends Config {
    @ConfigItem(
            keyName = "treeName",
            name = "Tree Name",
            description = "Name of the tree to chop",
            position = 1
    )
    default String treeName() {
        return "Tree";
    }

    @ConfigItem(
            keyName = "powerChop",
            name = "Power Chop",
            description = "Drop logs instead of banking",
            position = 2
    )
    default boolean powerChop() {
        return true;
    }
}

// ----- AutoWoodcutterPlugin (net.runelite.client.plugins.microbot.woodcutter) -----
@PluginDescriptor(
        name = "Auto Woodcutter",
        description = "Microbot woodcutting plugin",
        tags = {"woodcutting", "microbot", "skilling"},
        enabledByDefault = false
)
@Slf4j
public class AutoWoodcutterPlugin extends Plugin {
    @Inject
    private AutoWoodcutterConfig config;

    @Provides
    AutoWoodcutterConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(AutoWoodcutterConfig.class);
    }

    @Inject
    private AutoWoodcutterScript woodcutterScript;

    @Override
    protected void startUp() throws AWTException {
        if (woodcutterScript == null) return;
        // FIX: Use .set() for AtomicBoolean
        Microbot.pauseAllScripts.set(false);
        woodcutterScript.run(config);
    }

    @Override
    protected void shutDown() {
        woodcutterScript.shutdown();
    }
}

// ----- AutoWoodcutterScript (net.runelite.client.plugins.microbot.woodcutter) -----
public class AutoWoodcutterScript extends Script {

    public boolean run(AutoWoodcutterConfig config) {
        System.out.println("[AutoWoodcutter] Script started!");

        mainScheduledFuture = scheduledExecutorService.scheduleWithFixedDelay(() -> {
            try {
                // 1. Basic Checks
                if (!Microbot.isLoggedIn()) return;
                if (Microbot.pauseAllScripts.get()) return;
                if (Rs2Player.isAnimating() || Rs2Player.isMoving()) return;

                // 2. Inventory Management
                if (Rs2Inventory.isFull()) {
                if (config.powerChop()) {
                Rs2Inventory.dropAll(x -> x.getName().toLowerCase().contains("logs"));
                } else {
                if (!Rs2Bank.isOpen()) {
                Rs2Bank.openBank();
                } else {
                Rs2Bank.depositAll(x -> x.getName().toLowerCase().contains("logs"));
                Rs2Bank.closeBank();
                }
                }
                return;
                }

                // 3. Find and Interact (Thread-Safe)
                // We use .invoke() to run this block on the main game thread.
                // This prevents "Interrupted waiting for client thread" errors.
                Microbot.getClientThread().invoke(() -> {
                String treeName = config.treeName();
                WorldPoint playerLocation = Rs2Player.getWorldLocation();

                // Find the closest tree using the Stream API
                Rs2TileObjectModel tree = Microbot.getRs2TileObjectCache().getStream()
                .filter(obj -> obj.getName() != null && obj.getName().equalsIgnoreCase(treeName))
                .min(Comparator.comparingInt(obj -> obj.getWorldLocation().distanceTo(playerLocation)))
                .orElse(null);

                if (tree != null) {
                System.out.println("[AutoWoodcutter] Found: " + treeName);
                // Interact directly inside this safe block
                tree.click("Chop down");
                }
                });

                // Sleep to avoid spamming the interact call while the player runs to the tree
                sleep(1500, 2000);

            } catch (Exception e) {
                System.out.println("[AutoWoodcutter] Error: " + e.getMessage());
            }
        }, 0, 1000, TimeUnit.MILLISECONDS);
        return true;
    }

    @Override
    public void shutdown() {
        super.shutdown();
        System.out.println("[AutoWoodcutter] Script stopped.");
    }
}
